_TRANSCRIPT_TOPIC_EN_RE = re.compile(
    r"\b(?:"
    r"earnings|call|guidance|capex|capital|expenditures?|revenue|margin|results|"
    r"outlook|transcript|conference|quarter|"
    r"q[1-4]|fy(?:\d{2,4})?|20\d\d"
    r")\b",
    re.IGNORECASE,
)
