# Manifest cwd token. After an exact match the bridge runs in data_root, the
# host path of Dalton's openclaw-data copy.
HOST_DATA_COPY_CWD = "var/dalton/openclaw-data"


class HostCommandRejected(ValueError):
    """A non-Bloomberg host command is not that job's manifest host entry."""


def _host_argv_is_usable(command_argv: Any) -> bool:
    if not isinstance(command_argv, list) or not command_argv:
        return False
    for item in command_argv:
        if not isinstance(item, str) or item == "" or "\x00" in item:
            return False
    return True


def _cwd_under_ocw(cwd: Any, ocw_root: Path) -> Path:
    """Keep ``cwd`` only when it is ``ocw_root`` or a child. Anything else stays at the root."""
    root = Path(ocw_root).resolve()
    if not isinstance(cwd, str) or not cwd.strip() or "\x00" in cwd:
        return root
    candidate = Path(cwd)
    if not candidate.is_absolute():
        candidate = root / candidate
    try:
        resolved = candidate.resolve()
    except OSError:
        return root
    if resolved == root or root in resolved.parents:
        return resolved
    return root


def _load_host_job_manifest():
    """Load the data-task manifest from this checkout. Fail closed for non-BBG jobs.

    The bridge runs under the host interpreter, which lacks the backend's
    dependencies. Importing ``src.dalton`` runs its package ``__init__`` and the
    backend settings, so load ``manifest.py`` by path; it needs only yaml and
    pydantic.
    """
    import importlib.util

    module_path = (
        Path(__file__).resolve().parents[2] / "src" / "dalton" / "data_jobs" / "manifest.py"
    )
    name = "_dalton_bridge_data_task_manifest"
    module = sys.modules.get(name)
    if module is None:
        spec = importlib.util.spec_from_file_location(name, module_path)
        if spec is None or spec.loader is None:
            raise ImportError(f"cannot load {module_path}")
        module = importlib.util.module_from_spec(spec)
        sys.modules[name] = module
        try:
            spec.loader.exec_module(module)
        except BaseException:
            sys.modules.pop(name, None)
            raise
    return module.load_data_task_manifest()


def _load_host_task_config_module() -> Any | None:
    """Load stdlib-only ``src/dalton/data_jobs/task_config.py`` without requiring backend ``src``."""
    canonical = "src.dalton.data_jobs.task_config"
    existing = sys.modules.get(canonical)
    if existing is not None:
        return existing
    if "src" not in sys.modules or sys.modules["src"] is not None:
        try:
            import importlib

            return importlib.import_module(canonical)
        except ImportError:
            pass
    fallback_name = "_dalton_bridge_data_task_config"
    cached = sys.modules.get(fallback_name)
    if cached is not None:
        return cached
    import importlib.util

    module_path = (
        Path(__file__).resolve().parents[2] / "src" / "dalton" / "data_jobs" / "task_config.py"
    )
    if not module_path.is_file():
        return None
    spec = importlib.util.spec_from_file_location(fallback_name, module_path)
    if spec is None or spec.loader is None:
        return None
    module = importlib.util.module_from_spec(spec)
    sys.modules[fallback_name] = module
    try:
        spec.loader.exec_module(module)
    except BaseException:
        sys.modules.pop(fallback_name, None)
        return None
    return module


def _read_host_data_tasks_env(cfg_path: Path) -> dict[str, str]:
    task_cfg = _load_host_task_config_module()
    if task_cfg is not None:
        return task_cfg.parse_data_tasks_env_file(cfg_path)
    values: dict[str, str] = {}
    if not cfg_path.is_file():
        return values
    for raw_line in cfg_path.read_text(encoding="utf-8").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("export "):
            line = line[len("export ") :].strip()
        if "=" not in line:
            continue
        k, v = line.split("=", 1)
        k, v = k.strip(), v.strip()
        if len(v) >= 2 and v[0] == v[-1] and v[0] in ("'", '"'):
            v = v[1:-1]
        if k:
            values[k] = v
    return values


def resolve_host_run_command_spec(
    *,
    job_key: str,
    command_argv: Any,
    cwd: Any,
    data_root: Path,
    ocw_root: Path,
) -> dict[str, str | list[str]]:
    """Choose the host-run command.

    Bloomberg pulls always run ``scripts/bbg_remote_refresh.sh`` under
    ``data_root``. Every other job is accepted only when ``job_key`` is a
    ``runner: host`` manifest entry and both ``command_argv`` and ``cwd``
    equal that entry. Unknown jobs and drifted arguments raise
    ``HostCommandRejected`` and do not fall back to the Bloomberg script.
    The manifest cwd token ``var/dalton/openclaw-data`` then becomes
    ``data_root`` for the process cwd and ``OPENCLAW_WORKSPACE``.
    """
    _ = ocw_root
    root = Path(data_root)
    bbg_argv = ["bash", str(root / "scripts" / "bbg_remote_refresh.sh")]
    key = str(job_key or "").strip()
    if key in BBG_HOST_JOB_KEYS:
        return {
            "command_argv": bbg_argv,
            "cwd": str(root),
            "workspace_env": str(root),
        }
    try:
        manifest = _load_host_job_manifest()
        entry = manifest.by_job_key().get(key)
    except Exception as exc:
        raise HostCommandRejected("host manifest unavailable") from exc
    if entry is None or entry.runner != "host":
        raise HostCommandRejected(f"unknown host job: {key}")
    expected_argv = [str(item) for item in entry.command_argv]
    if not _host_argv_is_usable(command_argv) or list(command_argv) != expected_argv:
        raise HostCommandRejected("host command_argv does not match the manifest")
    expected_cwd = str(entry.cwd)
    if not isinstance(cwd, str) or cwd != expected_cwd:
        raise HostCommandRejected("host cwd does not match the manifest")
    resolved = root if expected_cwd == HOST_DATA_COPY_CWD else Path(expected_cwd)
    task_cfg = _load_host_task_config_module()
    expanded_argv: list[str] = []
    cfg_cache: dict[str, str] | None = None
    for item in expected_argv:
        m = re.fullmatch(r"\$\{(DALTON_DATA_TASK_[A-Z0-9_]+)\}", item)
        if not m:
            expanded_argv.append(item)
            continue
        env_key = m.group(1)
        val = (os.environ.get(env_key) or "").strip()
        if not val:
            if cfg_cache is None:
                cfg_override = (os.environ.get("DALTON_DATA_TASKS_CONFIG") or "").strip()
                if cfg_override:
                    mapped_host = (
                        task_cfg.resolve_data_tasks_config_host_path(
                            cfg_override,
                            host_data_root=resolved,
                        )
                        if task_cfg is not None
                        and hasattr(task_cfg, "resolve_data_tasks_config_host_path")
                        else None
                    )
                    if mapped_host is not None:
                        cfg_path = mapped_host
                    else:
                        cfg_path = Path(cfg_override)
                        if not cfg_path.is_absolute():
                            cfg_path = resolved / cfg_path
                else:
                    cfg_path = resolved / "config" / "data_tasks.env"
                cfg_cache = _read_host_data_tasks_env(cfg_path)
            val = (cfg_cache.get(env_key) or "").strip()
        if not val and task_cfg is not None and hasattr(task_cfg, "get_everflow_data_task_default"):
            val = str(task_cfg.get_everflow_data_task_default(env_key) or "").strip()
        if not val or "\x00" in val:
            raise HostCommandRejected(f"未配置 {env_key}（请设置环境变量或在 config/data_tasks.env 中配置）")
        expanded_argv.append(val)
    return {
        "command_argv": expanded_argv,
        "cwd": str(resolved),
        "workspace_env": str(resolved),
    }


# DALTON-HOOK(host-job-secrets): resolve host-task Vault secrets & manifest plain env
def _resolve_host_task_manifest_entry(job_key: str) -> Any | None:
    key = str(job_key or "").strip()
    if not key:
        return None
    try:
        manifest = _load_host_job_manifest()
        entry = manifest.by_job_key().get(key)
    except Exception:
        return None
    if entry is None or getattr(entry, "runner", None) != "host":
        return None
    return entry


def _resolve_host_task_env_from_manifest(
    job_key: str,
    *,
    requested_secrets: Any = None,
) -> tuple[dict[str, str], dict[str, str]]:
    """Filter Vault-supplied secrets against `manifest.yaml` `secret_names` and return `(accepted_secrets, plain_env)`.

    Never reads host-task secrets from bridge `os.environ`. Undeclared keys sent by a
    caller are dropped and logged (names only); missing declared keys are logged as
    warnings (names only) and do not block execution.
    """
    entry = _resolve_host_task_manifest_entry(job_key)
    declared_names: list[str] = (
        [str(s).strip() for s in getattr(entry, "secret_names", ()) if str(s).strip()]
        if entry is not None
        else []
    )
    declared_set = set(declared_names)
    plain_env: dict[str, str] = (
        {
            str(k).strip(): str(v)
            for k, v in (getattr(entry, "env", None) or {}).items()
            if str(k).strip() and v is not None
        }
        if entry is not None
        else {}
    )

    accepted_secrets: dict[str, str] = {}
    if isinstance(requested_secrets, Mapping):
        undeclared = sorted(
            str(k).strip()
            for k in requested_secrets.keys()
            if str(k).strip() and str(k).strip() not in declared_set
        )
        if undeclared:
            logger.warning(
                "Dropping undeclared host secret(s) for job_key=%s: %s",
                job_key,
                ", ".join(undeclared),
            )
        for name in declared_names:
            val = requested_secrets.get(name)
            if val is not None and str(val) != "":
                accepted_secrets[name] = str(val)

    missing = [name for name in declared_names if name not in accepted_secrets]
    if missing:
        logger.warning(
            "Host task %s starting with missing Vault secret(s): %s",
            job_key,
            ", ".join(missing),
        )
    return accepted_secrets, plain_env


def parse_notify_target(raw: str) -> tuple[str, str]:
    """Split a notify target into ``(channel, '<kind>:<id>')``.

    Accepts ``feishu:user:`` / ``feishu:chat:`` / ``discord:user:`` and
    ``discord:channel:<5-32 digits>``. The Discord channel form is what the
    OpenClaw message tool expects (``channel:<id>``).
    """
    if not isinstance(raw, str):
        raise ValueError("Target must be a string")
    cleaned = raw.strip()
    m_feishu = _FEISHU_TARGET_RE.match(cleaned)
    if m_feishu:
        return "feishu", m_feishu.group(1)
    m_chat = _FEISHU_CHAT_TARGET_RE.match(cleaned)
    if m_chat:
        return "feishu", m_chat.group(1)
    m_discord = _DISCORD_TARGET_RE.match(cleaned)
    if m_discord:
        return "discord", m_discord.group(1)
    m_channel = _DISCORD_CHANNEL_TARGET_RE.match(cleaned)
    if m_channel:
        return "discord", f"channel:{m_channel.group(1)}"
    raise ValueError(f"Unsupported notify target format: {cleaned!r}")


def build_feishu_send_card_cmd(
    *,
    script_path: Path | str,
    receive_id: str,
    card_json_file: Path | str,
    receive_id_type: str = "open_id",
    dry_run: bool = False,
) -> list[str]:
    """Build subprocess argv for ``feishu_send_card.py``.

    ``receive_id_type`` selects the id namespace of ``receive_id``: ``open_id``
    for a personal DM, ``chat_id`` for a group the OpenClaw bot is in (both are
    the script's own ``--receive-id-type`` choices).
    """
    cmd = [
        "python3",
        str(script_path),
        "--chat-id",
        str(receive_id),
        "--receive-id-type",
        receive_id_type,
        "--card-json-file",
        str(card_json_file),
        "--json",
    ]
    if dry_run:
        cmd.append("--dry-run")
    return cmd


def _resolve_and_validate_notify_image_path(
    raw_path: str,
    *,
    data_root: Path,
    run_id: str | None = None,
) -> Path:
    """Resolve and validate that an image file path stays strictly inside ``data_root``."""
    cleaned = str(raw_path or "").strip()
    if not cleaned:
        raise ValueError("invalid_image_path: empty image path")

    p = Path(cleaned)
    if ".." in p.parts:
        raise ValueError("invalid_image_path: path traversal ('..') is forbidden")

    resolved_root = data_root.resolve()
    cleaned_run_id: str | None = None
    if run_id is not None and str(run_id).strip():
        cleaned_run_id = str(run_id).strip()
        if (
            "/" in cleaned_run_id
            or "\\" in cleaned_run_id
            or ".." in Path(cleaned_run_id).parts
        ):
            raise ValueError("invalid_image_path: invalid run_id")

    container_prefixes: list[str] = []
    custom_prefix = os.environ.get("DALTON_CONTAINER_WORKSPACE_PREFIX", "").strip()
    if custom_prefix:
        container_prefixes.append(custom_prefix.rstrip("/") + "/")
    # Container data-tasks still mount var/dalton/openclaw-data at this path inside Docker.
    container_prefixes.append("/Users/everflow/.openclaw/workspace/")
    matched_prefix = next((pref for pref in container_prefixes if cleaned.startswith(pref)), "")
    if p.is_absolute():
        if matched_prefix:
            rel_str = cleaned[len(matched_prefix) :].lstrip("/")
            if not rel_str or ".." in Path(rel_str).parts:
                raise ValueError(
                    "invalid_image_path: invalid workspace-relative image path"
                )
            candidate = resolved_root / rel_str
        else:
            candidate = p
    else:
        if cleaned_run_id:
            run_candidate = resolved_root / ".dalton-runs" / cleaned_run_id / p
            root_candidate = resolved_root / p
            candidate = (
                run_candidate
                if (run_candidate.exists() or not root_candidate.exists())
                else root_candidate
            )
        else:
            candidate = resolved_root / p

    if candidate.is_symlink():
        raise ValueError("invalid_image_path: symlinks are not allowed")

    resolved = candidate.resolve()
    if not resolved.is_relative_to(resolved_root) or resolved == resolved_root:
        raise ValueError(
            "invalid_image_path: image path must resolve inside data volume"
        )

    cur_dir = candidate.parent
    while True:
        if cur_dir.is_symlink():
            target_dir = cur_dir.resolve()
            if not target_dir.is_relative_to(resolved_root):
                raise ValueError("invalid_image_path: symlink escapes data volume")
        if cur_dir == resolved_root or cur_dir.parent == cur_dir:
            break
        cur_dir = cur_dir.parent

    return resolved


def _prepare_notify_card_with_images(
    card: dict[str, Any],
    images: Any,
    *,
    data_root: Path,
    run_id: str | None = None,
) -> dict[str, Any]:
    """Validate ``images`` and ``__img__`` elements in ``card`` against ``data_root`` and rewrite ``__img__`` paths in a copy."""
    prepared = json.loads(json.dumps(card))
    placeholder_map: dict[str, str] = {}
    ordered_resolved: list[str] = []

    if images is not None:
        if not isinstance(images, list):
            raise ValueError("invalid_images: images must be a list")
        for item in images:
            if not isinstance(item, Mapping):
                raise ValueError(
                    "invalid_images: each image entry must be an object"
                )
            raw_path = item.get("path")
            if not isinstance(raw_path, str) or not raw_path.strip():
                raise ValueError(
                    "invalid_image_path: image entry path must be a non-empty string"
                )
            resolved_path = _resolve_and_validate_notify_image_path(
                raw_path,
                data_root=data_root,
                run_id=run_id,
            )
            resolved_str = str(resolved_path)
            ordered_resolved.append(resolved_str)
            raw_ph = item.get("placeholder")
            if isinstance(raw_ph, str) and raw_ph.strip():
                placeholder_map[raw_ph.strip()] = resolved_str
                placeholder_map[raw_ph] = resolved_str

    img_counter = 0

    def _rewrite_elements(elements: list[Any]) -> None:
        nonlocal img_counter
        for el in elements:
            if not isinstance(el, dict):
                continue
            if el.get("tag") == "__img__":
                raw_el_path = el.get("path")
                if not isinstance(raw_el_path, str) or not raw_el_path.strip():
                    raise ValueError(
                        "invalid_image_path: __img__ element missing path"
                    )
                if raw_el_path in placeholder_map:
                    el["path"] = placeholder_map[raw_el_path]
                elif raw_el_path.strip() in placeholder_map:
                    el["path"] = placeholder_map[raw_el_path.strip()]
                elif img_counter < len(ordered_resolved) and not placeholder_map:
                    el["path"] = ordered_resolved[img_counter]
                else:
                    resolved_el = _resolve_and_validate_notify_image_path(
                        raw_el_path,
                        data_root=data_root,
                        run_id=run_id,
                    )
                    el["path"] = str(resolved_el)
                img_counter += 1
            elif el.get("tag") == "collapsible_panel" and isinstance(
                el.get("elements"), list
            ):
                _rewrite_elements(el["elements"])

    body_obj = prepared.get("body")
    if isinstance(body_obj, dict) and isinstance(body_obj.get("elements"), list):
        _rewrite_elements(body_obj["elements"])
    if isinstance(prepared.get("elements"), list):
        _rewrite_elements(prepared["elements"])

    return prepared


def _run_feishu_send_card(
    *,
    script_path: Path,
    receive_id: str,
    card: dict[str, Any],
    receive_id_type: str = "open_id",
    timeout_s: float = FEISHU_SEND_CARD_TIMEOUT_S,
    dry_run: bool = False,
    feishu_app_id: str = "",
    feishu_app_secret: str = "",
    feishu_default_grant_chat_id: str = "",
) -> dict[str, Any]:
    """Invoke ``feishu_send_card.py`` with a temporary ``--card-json-file`` for Feishu card delivery.

    Supplies only the explicit Bridge Feishu sending credentials while stripping
    all unrelated ASR/TOS, gateway, broker, and Bridge tokens. Never logs or
    returns subprocess stdout/stderr. Only reports ``ok`` and ``exit_code``.
    """
    tmp_path: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w",
            suffix=".json",
            prefix="dalton_feishu_card_",
            encoding="utf-8",
            delete=False,
        ) as fh:
            json.dump(card, fh, ensure_ascii=False)
            tmp_path = Path(fh.name)

        cmd = build_feishu_send_card_cmd(
            script_path=script_path,
            receive_id=receive_id,
            card_json_file=tmp_path,
            receive_id_type=receive_id_type,
            dry_run=dry_run,
        )
        eff_app_id = feishu_app_id or os.environ.get("FEISHU_APP_ID", "")
        eff_app_secret = feishu_app_secret or os.environ.get("FEISHU_APP_SECRET", "")
        eff_grant_chat_id = feishu_default_grant_chat_id or os.environ.get(
            "FEISHU_DEFAULT_GRANT_CHAT_ID", ""
        )
        subproc_env = bridge_subprocess_env.build_feishu_card_send_subprocess_env(
            os.environ,
            feishu_app_id=eff_app_id,
            feishu_app_secret=eff_app_secret,
            feishu_default_grant_chat_id=eff_grant_chat_id,
        )
        proc = subprocess.run(
            cmd,
            env=subproc_env,
            capture_output=True,
            text=True,
            timeout=timeout_s,
            check=False,
        )
        parsed_out: dict[str, Any] | None = None
        if not dry_run and proc.stdout and proc.stdout.strip():
            try:
                candidate = json.loads(proc.stdout)
                if isinstance(candidate, dict):
                    parsed_out = candidate
            except ValueError:
                parsed_out = None
        discord_mirror = (
            parsed_out.get("discord_mirror")
            if isinstance(parsed_out, dict)
            else None
        )
        mirror_import_failed = (
            isinstance(discord_mirror, dict)
            and discord_mirror.get("status") == "import_error"
        ) or (
            isinstance(parsed_out, dict)
            and parsed_out.get("error") == "eve_tracking_mirror_import_failed"
        )
        if proc.returncode != 0:
            if mirror_import_failed:
                return {
                    "ok": False,
                    "exit_code": proc.returncode,
                    "feishu_sent": bool(parsed_out and parsed_out.get("feishu_sent")),
                    "error": "discord_mirror_import_failed",
                }
            return {
                "ok": False,
                "exit_code": proc.returncode,
                "error": f"exit_code={proc.returncode}",
            }
        if mirror_import_failed:
            return {
                "ok": False,
                "exit_code": proc.returncode,
                "feishu_sent": bool(parsed_out and parsed_out.get("feishu_sent")),
                "error": "discord_mirror_import_failed",
            }
        if isinstance(parsed_out, dict) and parsed_out.get("status") == "error":
            return {
                "ok": False,
                "exit_code": proc.returncode,
                "error": "feishu_api_error",
            }
        return {"ok": True, "exit_code": proc.returncode}
    except subprocess.TimeoutExpired:
        return {"ok": False, "exit_code": -1, "error": "timeout"}
    finally:
        if tmp_path is not None:
            try:
                tmp_path.unlink(missing_ok=True)
            except OSError:
                pass


# ---------------------------------------------------------------------------
# Feishu OpenAPI proxy (DALTON-HOOK(feishu-docs))
#
# All Feishu calls run here on the host with app identity
# (tenant_access_token). Credentials come from dedicated Bridge configuration
# (FEISHU_APP_ID / FEISHU_APP_SECRET in DALTON_BRIDGE_ENV_FILE); they are never
# logged and never appear in any route response.
# ---------------------------------------------------------------------------

FEISHU_API_BASE = "https://open.feishu.cn"
FEISHU_TOKEN_REFRESH_MARGIN_S = 300.0
FEISHU_MAX_CONTENT_CHARS = 50000
FEISHU_DEFAULT_CONTENT_CHARS = 20000
FEISHU_PAGE_SIZE = 50
FEISHU_MAX_PAGES = 20
# C2: a markdown image bound into a docx image block — Feishu's upload cap is
# 20 MB; the bridge's own ceiling stays below it, and the HTTP envelope for
# the feishu routes is sized to carry one document's worth of inline images.
FEISHU_IMAGE_MAX_BYTES = 10 * 1024 * 1024
FEISHU_IMAGE_TOTAL_MAX_BYTES = 20 * 1024 * 1024
FEISHU_DOC_IMAGE_BLOCK_TYPE = 27
FEISHU_IMAGE_ALLOWED_EXTENSIONS = frozenset({".png", ".jpg", ".jpeg", ".webp", ".gif"})
# C2: the /feishu/doc/create|append bodies carry inline image bytes (base64),
# so they need the wiki-ingest-sized envelope, not the 256 KiB MCP default.
MAX_FEISHU_DOC_REQUEST_BYTES = 30 * 1024 * 1024

# URL path segment -> doc kind (docs is the legacy docx path; both carry a docx token)
_FEISHU_LINK_KINDS: dict[str, str] = {"wiki": "wiki", "docx": "docx", "docs": "docx"}

# C2: markdown image references, in order of appearance — the Nth converted
# image block binds to the Nth reference.
_MARKDOWN_IMAGE_RE = re.compile(r"!\[[^\]\n]*\]\(\s*([^)\s]+)(?:\s+\"[^\"]*\")?\s*\)")


def _markdown_image_refs(markdown: str, *, dedup: bool = True) -> list[str]:
    refs: list[str] = []
    for match in _MARKDOWN_IMAGE_RE.finditer(markdown or ""):
        ref = match.group(1).strip()
        if ref and (not dedup or ref not in refs):
            refs.append(ref)
    return refs


def _feishu_image_ip_blocked(ip: str) -> bool:
    """Whether *ip* is a private/loopback/link-local/reserved/unspecified/multicast address.

    The rule is the backend SSRF guard's ``_ip_is_blocked``
    (src/tools/web/inhouse/guard.py), restated here because the bridge is a
    standalone host process and cannot import backend code.
    """
    addr = ipaddress.ip_address(ip)
    return (
        addr.is_private
        or addr.is_loopback
        or addr.is_link_local
        or addr.is_reserved
        or addr.is_unspecified
        or addr.is_multicast
    )


def _feishu_image_url_block_reason(url: str) -> str | None:
    """Why this URL may not be fetched host-side, or None if it may (C2).

    Same semantics as the crawler's check, restated locally: the bridge is a
    standalone host process and cannot import the sandbox-side copy. This is
    the literal-address half — the fetch itself resolves hostnames and
    re-checks every redirect hop (see `_feishu_image_fetch`).
    """
    try:
        parsed = urllib.parse.urlparse(url)
    except ValueError as exc:
        return f"unparseable URL ({exc})"
    if parsed.scheme not in ("http", "https"):
        return f"URL must be http(s), got scheme {parsed.scheme!r}"
    hostname = parsed.hostname or ""
    if hostname in ("", "localhost"):
        return "access to localhost is not allowed"
    try:
        ipaddress.ip_address(hostname)
    except ValueError:
        return None  # a name, not a literal address — the fetch resolves it
    if _feishu_image_ip_blocked(hostname):
        return f"access to private/reserved address {hostname} is not allowed"
    return None


class _PinnedHTTPConnection(http.client.HTTPConnection):
    """An HTTP connection whose TCP dial goes to one specific, SSRF-checked IP.

    ``self.host`` keeps the URL's hostname, so the ``Host`` header is
    unchanged; only the socket's target address is pinned. This closes the
    rebinding window where the check resolves the name once and the client
    resolves it again (C2/r3).
    """

    def __init__(self, host: str, port: int | None = None, *, pinned_ip: str,
                 timeout: float = 30.0) -> None:
        super().__init__(host, port, timeout=timeout)
        self._pinned_ip = pinned_ip

    def connect(self) -> None:
        # stdlib connect with the dial aimed at the checked address instead of
        # resolving `self.host` again.
        self.sock = self._create_connection(
            (self._pinned_ip, self.port), self.timeout, self.source_address
        )
        if self._tunnel_host:
            self._tunnel()


class _PinnedHTTPSConnection(http.client.HTTPSConnection):
    """An HTTPS connection dialed to a checked IP with the TLS handshake kept
    on the URL's hostname: SNI (``server_hostname``) and the certificate's
    hostname validation both check the name the URL carried, not the pinned
    address."""

    def __init__(self, host: str, port: int | None = None, *, pinned_ip: str,
                 timeout: float = 30.0) -> None:
        super().__init__(host, port, timeout=timeout)
        self._pinned_ip = pinned_ip

    def connect(self) -> None:
        self.sock = self._create_connection(
            (self._pinned_ip, self.port), self.timeout, self.source_address
        )
        if self._tunnel_host:
            self._tunnel()
        self.sock = self._context.wrap_socket(self.sock, server_hostname=self.host)


#: Manual redirect budget for one external image fetch (C2/SSRF).
FEISHU_IMAGE_MAX_REDIRECTS = 3
_FEISHU_IMAGE_REDIRECT_CODES = frozenset({301, 302, 303, 307, 308})
_FEISHU_IMAGE_FETCH_TIMEOUT_S = 30.0


def _feishu_image_open_connection(
    parsed_url: urllib.parse.ParseResult, *, pinned_ip: str, timeout_s: float
) -> http.client.HTTPConnection:
    """The hop's http.client connection, dialed to *pinned_ip* (the address
    the SSRF check approved) while Host/SNI/cert-hostname stay on the original
    name. A seam the tests replace instead of the dialing logic itself."""
    hostname = parsed_url.hostname or ""
    port = parsed_url.port or (443 if parsed_url.scheme == "https" else 80)
    conn_cls = _PinnedHTTPSConnection if parsed_url.scheme == "https" else _PinnedHTTPConnection
    return conn_cls(hostname, port, pinned_ip=pinned_ip, timeout=timeout_s)


def _feishu_image_fetch(url: str) -> tuple[bytes, str]:
    """Download an external image under the SSRF checks; ``(bytes, final_url)``.

    Every hop — the original URL and up to 3 redirects — must be http(s), its
    host's DNS answers must hold no private/loopback/link-local/reserved
    address, and the connection is pinned to the address that passed the
    check: the socket never resolves the hostname again, so a rebinding answer
    arriving between check and connect cannot aim the dial at an internal
    address. Redirects are followed by hand (never automatically) so each hop
    goes back through the same checks.
    """
    current = url
    for _hop in range(FEISHU_IMAGE_MAX_REDIRECTS + 1):
        reason = _feishu_image_url_block_reason(current)
        if reason is not None:
            raise FeishuApiError("image_url_blocked", reason)
        try:
            parsed = urllib.parse.urlparse(current)
        except ValueError as exc:
            raise FeishuApiError("image_url_blocked", f"unparseable URL ({exc})") from exc
        hostname = parsed.hostname or ""
        try:
            addr_infos = socket.getaddrinfo(hostname, None)
        except socket.gaierror as exc:
            raise FeishuApiError(
                "image_url_blocked", f"DNS resolution failed for {hostname!r} ({exc})"
            ) from exc
        blocked = sorted(
            {info[4][0] for info in addr_infos if _feishu_image_ip_blocked(info[4][0])}
        )
        if blocked:
            raise FeishuApiError(
                "image_url_blocked",
                f"host {hostname!r} resolves to private/reserved address {blocked[0]}",
            )
        request_target = parsed.path or "/"
        if parsed.query:
            request_target += f"?{parsed.query}"
        conn = _feishu_image_open_connection(
            parsed, pinned_ip=addr_infos[0][4][0], timeout_s=_FEISHU_IMAGE_FETCH_TIMEOUT_S
        )
        try:
            conn.request(
                "GET",
                request_target,
                headers={
                    "User-Agent": "dalton-researchdata-bridge/1.0",
                    "Accept": "*/*",
                },
            )
            resp = conn.getresponse()
            if resp.status in _FEISHU_IMAGE_REDIRECT_CODES:
                location = resp.getheader("Location")
                if location:
                    if _hop == FEISHU_IMAGE_MAX_REDIRECTS:
                        raise FeishuApiError(
                            "image_url_blocked",
                            f"more than {FEISHU_IMAGE_MAX_REDIRECTS} redirects fetching {url}",
                        )
                    current = urllib.parse.urljoin(current, location)
                    continue
            if not 200 <= resp.status < 300:
                raise FeishuApiError("image_fetch_failed", f"HTTP {resp.status}")
            data = resp.read(FEISHU_IMAGE_MAX_BYTES + 1)
            return data, current
        except FeishuApiError:
            raise
        except (http.client.HTTPException, OSError) as exc:
            raise FeishuApiError(
                "feishu_network_error", f"{type(exc).__name__}: {exc}"[:200]
            ) from exc
        finally:
            conn.close()
    raise FeishuApiError(
        "image_url_blocked", f"more than {FEISHU_IMAGE_MAX_REDIRECTS} redirects fetching {url}"
    )


def _feishu_image_payload(
    ref: str, image_files: dict[str, Any]
) -> tuple[bytes, str]:
    """``(bytes, filename)`` for one image reference (C2).

    Workspace paths arrive pre-read from the caller as base64 (the sandbox's
    files are not host paths); external links are fetched here under the
    SSRF check and the size ceiling.
    """
    supplied = image_files.get(ref)
    if isinstance(supplied, dict):
        raw = supplied.get("content_b64")
        if isinstance(raw, str) and raw.strip():
            data = base64.b64decode(raw, validate=False)
            filename = str(supplied.get("filename") or "image.png")
            if len(data) > FEISHU_IMAGE_MAX_BYTES:
                raise FeishuApiError("image_too_large", f"{len(data)} bytes")
            return data, filename
        raise FeishuApiError("image_payload_invalid", "content_b64 missing")
    if ref.startswith(("http://", "https://")):
        data, final_url = _feishu_image_fetch(ref)
        if len(data) > FEISHU_IMAGE_MAX_BYTES:
            raise FeishuApiError("image_too_large", f"{len(data)} bytes")
        if not data:
            raise FeishuApiError("image_empty")
        path_name = urllib.parse.urlparse(final_url).path or "image"
        filename = Path(path_name).name or "image"
        if Path(filename).suffix.lower() not in FEISHU_IMAGE_ALLOWED_EXTENSIONS:
            filename = filename + ".png" if "." not in filename else filename
        return data, filename
    raise FeishuApiError(
        "image_unavailable",
        "本地路径未随请求提供图片字节（调用方需读取工作区文件后以 image_files 传入）",
    )


def _feishu_image_block_bound(client: FeishuClient, document_id: str, block_id: str) -> bool:
    """Whether the image block carries a bound media token (the verify half of C2)."""
    try:
        block = client.get_block(document_id, block_id)
    except FeishuApiError:
        return False
    image = block.get("image") if isinstance(block.get("image"), dict) else {}
    return bool(str(image.get("token") or ""))


def _resolve_inserted_image_block_ids(
    converted_blocks: list[dict[str, Any]] | None,
    insert_response: dict[str, Any] | None,
) -> list[str]:
    """Resolve converted placeholder image blocks to actual document ``block_id``s
    from the descendant-insert response (``block_id_relations`` or ``children``)."""
    if not isinstance(insert_response, dict):
        return []
    relations = insert_response.get("block_id_relations")
    if isinstance(relations, list) and converted_blocks:
        rel_map = {
            str(r.get("temporary_block_id") or ""): str(r.get("block_id") or "")
            for r in relations
            if isinstance(r, dict)
            and str(r.get("temporary_block_id") or "")
            and str(r.get("block_id") or "")
        }
        conv_img_ids = [
            str(b.get("block_id") or "")
            for b in converted_blocks
            if isinstance(b, dict) and b.get("block_type") == FEISHU_DOC_IMAGE_BLOCK_TYPE
        ]
        if conv_img_ids and all(cid in rel_map for cid in conv_img_ids):
            return [rel_map[cid] for cid in conv_img_ids]
    children = insert_response.get("children")
    if isinstance(children, list):
        child_img_ids = [
            str(b.get("block_id") or "")
            for b in children
            if isinstance(b, dict)
            and b.get("block_type") == FEISHU_DOC_IMAGE_BLOCK_TYPE
            and str(b.get("block_id") or "")
        ]
        if child_img_ids:
            return child_img_ids
    return []


def bind_docx_images(
    client: FeishuClient,
    document_id: str,
    markdown: str,
    image_files: dict[str, Any],
    *,
    converted_blocks: list[dict[str, Any]] | None = None,
    insert_response: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Upload and bind every markdown image the convert step left as a
    placeholder block (C2). Returns ``{total, bound, failed}``; each failed
    entry carries the reference, block id and a reason. Runs on the caller's
    thread (the handlers already run inside ``asyncio.to_thread``).
    """
    all_refs = _markdown_image_refs(markdown, dedup=False)
    unique_refs = _markdown_image_refs(markdown, dedup=True)
    if not all_refs:
        return {"total": 0, "bound": 0, "failed": []}

    placeholder_ids = _resolve_inserted_image_block_ids(converted_blocks, insert_response)
    if not placeholder_ids:
        blocks = client.list_blocks(document_id)
        placeholder_ids = [
            str(b.get("block_id") or "")
            for b in blocks
            if b.get("block_type") == FEISHU_DOC_IMAGE_BLOCK_TYPE
            and not str((b.get("image") or {}).get("token") or "")
            and str(b.get("block_id") or "")
        ]

    if len(placeholder_ids) == len(all_refs):
        refs = all_refs
    elif len(placeholder_ids) == len(unique_refs):
        refs = unique_refs
    else:
        return {
            "total": len(all_refs),
            "bound": 0,
            "failed": [
                {
                    "ref": ref,
                    "block_id": "",
                    "reason": (
                        f"文档中的占位图片块（{len(placeholder_ids)}）与 markdown 图片"
                        f"（{len(all_refs)}）数量不一致，无法一一对应绑定"
                    ),
                }
                for ref in all_refs
            ],
        }
    bound = 0
    failures: list[dict[str, str]] = []
    for block_id, ref in zip(placeholder_ids, refs):
        try:
            data, filename = _feishu_image_payload(ref, image_files)
            file_token = client.upload_docx_image(
                document_id=document_id,
                image_block_id=block_id,
                filename=filename,
                data=data,
            )
            if file_token:
                try:
                    client.replace_block_image(document_id, block_id, file_token)
                except FeishuApiError:
                    pass
            if _feishu_image_block_bound(client, document_id, block_id):
                bound += 1
                continue
            # The asset is up but the block did not take it; the document id
            # is the other documented spelling of the docx_image upload point.
            file_token_retry = client.upload_docx_image(
                document_id=document_id,
                image_block_id=document_id,
                filename=filename,
                data=data,
            )
            if file_token_retry:
                try:
                    client.replace_block_image(document_id, block_id, file_token_retry)
                except FeishuApiError:
                    pass
            if _feishu_image_block_bound(client, document_id, block_id):
                bound += 1
                continue
            failures.append(
                {
                    "ref": ref,
                    "block_id": block_id,
                    "reason": "素材已上传但图片块未绑定 token（回读校验失败）",
                }
            )
        except FeishuApiError as exc:
            failures.append(
                {"ref": ref, "block_id": block_id, "reason": f"{exc.error_code}: {str(exc)[:120]}"}
            )
        except Exception as exc:
            failures.append(
                {"ref": ref, "block_id": block_id, "reason": f"{type(exc).__name__}: {exc}"[:160]}
            )
    return {"total": len(refs), "bound": bound, "failed": failures}


class FeishuApiError(RuntimeError):
    """Feishu OpenAPI call failure. Never carries credentials or tokens.

    R7 §3: alongside the bridge-side ``error_code``, a refusal that reached a
    Feishu payload also carries it structured — ``feishu_code``/``feishu_msg``
    (the payload's own business code and msg, which `_request` used to embed
    only in the message text) and ``log_id`` (the request id Feishu names
    ``log_id``, older endpoints ``request_id``; "" when none came back). A
    multi-stage flow may attach ``phases`` so a later stage's failure cannot
    mask an earlier one's.
    """

    def __init__(
        self,
        error_code: str,
        message: str = "",
        *,
        feishu_code: str = "",
        feishu_msg: str = "",
        log_id: str = "",
        phases: list[dict[str, str]] | None = None,
    ) -> None:
        super().__init__(message or error_code)
        self.error_code = error_code
        self.feishu_code = feishu_code
        self.feishu_msg = feishu_msg
        self.log_id = log_id
        self.phases = phases


def _feishu_error_payload_ids(payload: dict[str, Any]) -> tuple[str, str, str]:
    """``(feishu_code, feishu_msg, log_id)`` from an error payload — the ids
    Feishu puts beside its own code/msg at the top level."""
    feishu_code = _log_redaction.clean_log_field(payload.get("code"), max_len=32)
    feishu_msg = str(payload.get("msg") or "")[:200]
    log_id = _log_redaction.clean_log_field(
        payload.get("log_id") or payload.get("request_id") or "", max_len=64
    )
    return feishu_code, feishu_msg, log_id


#: Feishu open_id shape — a user identifier the unified log redaction does
#: not know (`ou_…`). Scrubbed here, bridge-local; the shared
#: `log_redaction.py` is deliberately untouched (R7 r2, codex #1).
_FEISHU_OPEN_ID_RE = re.compile(r"\bou_[A-Za-z0-9_\-]+")
#: Strict validation for caller-supplied bound Feishu open_id (`ou_…`, <= 64
#: chars, letters/digits/underscore only). Anything else is treated as absent.
_FEISHU_BOUND_OPEN_ID_RE = re.compile(r"^ou_[A-Za-z0-9_]{1,61}$")


def _normalize_feishu_open_id(raw: Any) -> str:
    """Validate and return a Feishu ``open_id`` (``ou_...``, <=64 chars, alnum/underscore), or ``""``."""
    candidate = raw.strip() if isinstance(raw, str) else ""
    if not candidate or not _FEISHU_BOUND_OPEN_ID_RE.match(candidate):
        return ""
    return candidate


def _feishu_scrub_member_text(
    raw: str, member_ids: tuple[str, ...] = (), *, max_len: int = 120
) -> str:
    """Sanitize a Feishu msg destined for grant phases / logs / responses:
    the unified redaction chain first, then this request's own member ids
    (either spelling) and any other ``ou_…`` open_id replaced — Feishu's own
    msg may echo the member_id it refused, and that identifier must not
    survive anywhere. Truncation comes last so a redaction straddling the
    boundary still applies."""
    text = _log_redaction.clean_log_field(raw, max_len=max_len * 2)
    for member_id in member_ids:
        if member_id:
            text = text.replace(member_id, "[REDACTED]")
    text = _FEISHU_OPEN_ID_RE.sub("[REDACTED]", text)
    # Feishu's own token shapes (tenant/user access tokens, app ids) are not in
    # the unified chain; a msg that echoes one must not reach a phase (R7 r3).
    text = _FEISHU_AUTH_TOKEN_RE.sub("[REDACTED]", text)
    return text[:max_len]


#: Codes where Feishu never returned a definite verdict: the connection died
#: mid-response or the body was unparseable, so a write may have been committed
#: anyway. Callers must not claim nothing was written for these.
_FEISHU_UNKNOWN_OUTCOME_CODES: frozenset[str] = frozenset({
    "feishu_network_error",
    "feishu_invalid_response",
    "feishu_empty_error_response",
})


def _feishu_outcome_unknown(error_code: str) -> bool:
    """Whether a Feishu failure leaves it unknown if the write landed: no
    response, an unparseable or empty error body, or a 5xx (a gateway may
    answer after the upstream committed). Only a 4xx with a body is a refusal."""
    return error_code in _FEISHU_UNKNOWN_OUTCOME_CODES or error_code.startswith(
        "feishu_http_5"
    )


#: Default share target for docs the bot creates; override with
#: FEISHU_DEFAULT_GRANT_CHAT_ID (set empty string to disable).
FEISHU_DEFAULT_GRANT_CHAT_ID = "oc_397207208fb52a0b09969794ef3cd421"


def parse_feishu_token(raw: str) -> tuple[str, str]:
    """Split a docx/wiki URL or bare token into ``(kind, token)``.

    ``kind`` is ``"wiki"`` for wiki node tokens (``/wiki/<token>`` links),
    ``"docx"`` for document tokens (``/docx/<token>``, ``/docs/<token>``
    links), and ``""`` for a bare token, whose kind is resolved later by
    `resolve_feishu_document` (wiki node lookup first, then docx id).
    Query strings and fragments are ignored.
    """
    cleaned = str(raw or "").strip()
    if not cleaned:
        return "", ""
    if "://" in cleaned or cleaned.startswith("/"):
        try:
            parsed = urllib.parse.urlparse(cleaned if "://" in cleaned else f"https://x{cleaned}")
            segments = [seg for seg in (parsed.path or "").split("/") if seg]
        except ValueError:
            return "", ""
        for idx, seg in enumerate(segments):
            if seg in _FEISHU_LINK_KINDS and idx + 1 < len(segments):
                token = segments[idx + 1].strip()
                if token:
                    return _FEISHU_LINK_KINDS[seg], token
        return "", ""
    return "", cleaned


# Read-only fields the convert endpoint returns but the descendant-insert
# endpoint rejects (e.g. table-cell merge state). Dropped before inserting.
_FEISHU_BLOCK_READONLY_KEYS = frozenset({"merge_info"})

# Official docx block_type ids (see Feishu docx block docs / OpenClaw
# extensions/feishu/src/docx-table-ops.ts cleanBlocksForDescendant).
_FEISHU_BLOCK_TYPE_TABLE = 31
_FEISHU_BLOCK_TYPE_TABLE_CELL = 32

# Tenant link base for docs; derived from the API domain (the bridge never
# learns the tenant slug, so links are best-effort `<base>/docx/<id>`).
FEISHU_DOC_URL_BASE = FEISHU_API_BASE.replace("://open.", "://")


def _sanitize_feishu_block(block: Any) -> Any:
    """Make a convert-produced block submittable to the descendant-insert API.

    Mirrors OpenClaw's ``cleanBlocksForDescendant``: drop ``parent_id`` on every
    block; rebuild a table block's ``table.property`` keeping only the writable
    layout fields (``row_size`` / ``column_size`` / ``column_width`` — this
    drops read-only ``cells`` and ``merge_info``); normalize a table cell's
    string ``children`` to a list. Other read-only keys are still dropped
    recursively as belt-and-braces.
    """
    if isinstance(block, list):
        return [_sanitize_feishu_block(item) for item in block]
    if not isinstance(block, dict):
        return block
    clean = {k: v for k, v in block.items() if k != "parent_id"}
    block_type = clean.get("block_type")
    if block_type == _FEISHU_BLOCK_TYPE_TABLE_CELL and isinstance(clean.get("children"), str):
        clean["children"] = [clean["children"]]
    if block_type == _FEISHU_BLOCK_TYPE_TABLE and isinstance(clean.get("table"), dict):
        prop = clean["table"].get("property") or {}
        rebuilt = {
            k: prop[k]
            for k in ("row_size", "column_size", "column_width")
            if k in prop
        }
        clean["table"] = {"property": rebuilt}
    return {
        k: _sanitize_feishu_block(v)
        for k, v in clean.items()
        if k not in _FEISHU_BLOCK_READONLY_KEYS
    }


def feishu_doc_url(document_id: str, node_token: str = "") -> str:
    """Best-effort tenant link for a created document (wiki node links use the node token)."""
    return f"{FEISHU_DOC_URL_BASE}/wiki/{node_token}" if node_token else (
        f"{FEISHU_DOC_URL_BASE}/docx/{document_id}"
    )


def _soft_get_node(client: "FeishuClient", token: str, *, obj_type: str = "") -> dict[str, Any]:
    """`get_node` that maps "node not found"-shaped upstream answers to ``{}``.

    Transport failures still raise: only API-level rejections (error code or
    4xx/5xx payload) mean "this token is not a wiki node".
    """
    try:
        return client.get_node(token, obj_type=obj_type)
    except FeishuApiError as exc:
        if exc.error_code == "feishu_api_error" or exc.error_code.startswith("feishu_http_"):
            return {}
        raise


def _feishu_node_summary(node: dict[str, Any]) -> dict[str, Any]:
    """Normalize a wiki node for wire responses, keeping shortcut cross-space fields."""
    return {
        "node_token": str(node.get("node_token") or ""),
        "obj_token": str(node.get("obj_token") or ""),
        "obj_type": str(node.get("obj_type") or ""),
        "title": str(node.get("title") or ""),
        "space_id": str(node.get("space_id") or ""),
        "node_type": str(node.get("node_type") or ""),
        "origin_space_id": str(node.get("origin_space_id") or ""),
        "parent_node_token": str(node.get("parent_node_token") or ""),
        "has_child": bool(node.get("has_child")),
    }


def resolve_feishu_document(
    client: "FeishuClient", kind: str, token: str
) -> tuple[str, dict[str, Any]]:
    """Resolve a parsed token to ``(document_id, node)`` exactly once.

    ``/wiki/`` links resolve through ``get_node``; ``/docx/`` links reverse-look
    up their wiki node with ``obj_type=docx`` (empty node when not in a wiki);
    bare tokens try the wiki-node lookup first and fall back to treating the
    token as a docx document id. Callers must reuse this one resolution for
    both the permission check and the actual read/write.
    """
    if kind == "wiki":
        node = client.get_node(token)
        document_id = str(node.get("obj_token") or "")
        if not document_id:
            raise FeishuApiError("wiki_node_not_found")
        return document_id, node
    if kind == "docx":
        node = _soft_get_node(client, token, obj_type="docx")
        document_id = str(node.get("obj_token") or token)
        return document_id, node
    node = _soft_get_node(client, token)
    document_id = str(node.get("obj_token") or "")
    if document_id:
        return document_id, node
    return token, {}


def resolve_feishu_node_for_check(
    client: "FeishuClient", kind: str, token: str
) -> tuple[str, dict[str, Any]]:
    """Permission-check resolution: `resolve_feishu_document`, plus a docx reverse lookup.

    Unlike `resolve_feishu_document`, this never raises ``wiki_node_not_found``
    (an unresolvable token is simply "not in a wiki" — the caller denies), and
    a bare token that is NOT a wiki node gets one ``obj_type=docx`` reverse
    lookup so a bare docx token's wiki space can still be whitelist-checked
    instead of being rejected as `not_in_wiki` outright.
    """
    if kind == "wiki":
        node = _soft_get_node(client, token)
        return str(node.get("obj_token") or ""), node
    if kind == "docx":
        node = _soft_get_node(client, token, obj_type="docx")
        return str(node.get("obj_token") or token), node
    node = _soft_get_node(client, token)
    if node:
        return str(node.get("obj_token") or ""), node
    node = _soft_get_node(client, token, obj_type="docx")
    if node:
        return str(node.get("obj_token") or token), node
    return token, {}


_FEISHU_STATIC_PATH_SEGMENTS: frozenset[str] = frozenset({
    "open-apis", "auth", "v1", "v2", "v3", "tenant_access_token", "internal",
    "docx", "documents", "blocks", "convert", "raw_content", "descendant",
    "children", "wiki", "spaces", "get_node", "nodes", "drive", "permissions",
    "members", "files", "download", "medias", "upload_all", "contact", "users",
    "batch_get_id", "im", "messages", "chats", "bitable",
    "apps", "tables", "records", "fields",
})
_FEISHU_AUTH_TOKEN_RE = re.compile(
    r"(?i)\b(?:(?:t|u)-[A-Za-z0-9._\-]{6,}|cli_[A-Za-z0-9._\-]{6,})\b"
)
_FEISHU_DOC_ID_RE = re.compile(
    r"(?i)\b(?:doc|dox|wik|bas|box|fld)[A-Za-z0-9]{8,}\b"
)
_FEISHU_DYNAMIC_ID_KEYS: frozenset[str] = frozenset({
    "document_id",
    "block_id",
    "node_token",
    "space_id",
    "folder_token",
    "parent_node_token",
    "obj_token",
    "origin_node_token",
    "origin_space_id",
    "token",
    "member_id",
})


def _feishu_path_template(path: str) -> str:
    clean = urllib.parse.urlsplit(str(path or "")).path or "/"
    parts = [p for p in clean.split("/") if p]
    out: list[str] = []
    for i, seg in enumerate(parts):
        prev = parts[i - 1] if i > 0 else ""
        if prev == "documents" and seg not in _FEISHU_STATIC_PATH_SEGMENTS:
            out.append("{document_id}")
        elif prev == "blocks" and seg not in _FEISHU_STATIC_PATH_SEGMENTS:
            out.append("{block_id}")
        elif prev == "spaces" and seg not in _FEISHU_STATIC_PATH_SEGMENTS:
            out.append("{space_id}")
        elif prev == "permissions" and seg not in _FEISHU_STATIC_PATH_SEGMENTS:
            out.append("{token}")
        elif seg not in _FEISHU_STATIC_PATH_SEGMENTS:
            out.append("{token}")
        else:
            out.append(seg)
    return "/" + "/".join(out)


def _feishu_collect_dynamic_ids(node: Any, ids: list[str]) -> None:
    """Collect dynamic Feishu ids from a nested request payload, at any depth.

    An id-shaped key (`*_id`, `*_token`, plus `children`/`cells`, which carry
    bare block ids) marks every string under it — its own value or each string
    item of its list, e.g. `descendants[*].block_id` or a child block's
    `children` — as an id; everything else is only recursed into.
    """
    if isinstance(node, dict):
        for key, val in node.items():
            k = str(key)
            if k.endswith(("_id", "_token")) or k in ("children", "cells"):
                if isinstance(val, str):
                    if val.strip():
                        ids.append(val.strip())
                    continue
                if isinstance(val, list):
                    for item in val:
                        if isinstance(item, str):
                            if item.strip():
                                ids.append(item.strip())
                        else:
                            _feishu_collect_dynamic_ids(item, ids)
                    continue
            _feishu_collect_dynamic_ids(val, ids)
    elif isinstance(node, list):
        for item in node:
            _feishu_collect_dynamic_ids(item, ids)


def _feishu_request_dynamic_ids(
    path: str,
    query: dict[str, Any] | None = None,
    json_body: dict[str, Any] | None = None,
) -> tuple[str, ...]:
    clean = urllib.parse.urlsplit(str(path or "")).path or "/"
    ids: list[str] = [
        seg for seg in clean.split("/") if seg and seg not in _FEISHU_STATIC_PATH_SEGMENTS
    ]
    if isinstance(query, dict):
        for key, val in query.items():
            if key in _FEISHU_DYNAMIC_ID_KEYS and isinstance(val, str) and val.strip():
                ids.append(val.strip())
    _feishu_collect_dynamic_ids(json_body, ids)
    # Sort longest-first so a longer id is replaced before a shorter prefix.
    return tuple(sorted(set(ids), key=len, reverse=True))


def _sanitize_feishu_response_preview(
    raw: str,
    *,
    secrets: tuple[str, ...] = (),
    dynamic_ids: tuple[str, ...] = (),
    limit: int = 120,
) -> str:
    text = " ".join((raw or "").split())
    if not text:
        return ""
    for sec in secrets:
        if sec:
            text = text.replace(sec, "[REDACTED]")
    for did in dynamic_ids:
        if did:
            text = text.replace(did, "<id>")
    # Take the leading slice first (with a small lookahead buffer so tokens
    # straddling the boundary still match regexes) rather than calling
    # sanitize_stderr_text(), which truncates to the *last* 500 chars.
    text = text[: max(limit * 2, 240)]
    for pat, repl in _STDERR_SECRET_PATTERNS:
        text = pat.sub(repl, text)
    text = _FEISHU_AUTH_TOKEN_RE.sub("[REDACTED]", text)
    text = _FEISHU_DOC_ID_RE.sub("<id>", text)
    text = " ".join(text.split())
    return text[:limit]


class FeishuClient:
    """Minimal blocking Feishu OpenAPI client (tenant token + docx/wiki/permissions).

    Bridge handlers wrap every call in ``asyncio.to_thread``; the tenant token is
    cached in memory and refreshed ``FEISHU_TOKEN_REFRESH_MARGIN_S`` before expiry.
    """

    def __init__(self, app_id: str, app_secret: str, timeout_s: float = 30.0) -> None:
        self.app_id = app_id
        self.app_secret = app_secret
        self.timeout_s = timeout_s
        self._tenant_token = ""
        self._token_expires_at = 0.0

    def _tenant_access_token(self) -> str:
        now = time.time()
        if self._tenant_token and now < self._token_expires_at:
            return self._tenant_token
        body = self._request(
            "POST",
            "/open-apis/auth/v3/tenant_access_token/internal",
            json_body={"app_id": self.app_id, "app_secret": self.app_secret},
            with_auth=False,
            unwrap_data=False,
        )
        token = str(body.get("tenant_access_token") or "")
        expire_s = body.get("expire")
        if not token:
            raise FeishuApiError("feishu_auth_failed")
        try:
            ttl = max(60.0, float(expire_s)) if expire_s is not None else 7200.0
        except (TypeError, ValueError):
            ttl = 7200.0
        self._tenant_token = token
        self._token_expires_at = now + ttl - FEISHU_TOKEN_REFRESH_MARGIN_S
        return token

    def _invalid_response_detail(
        self,
        status: int,
        content_type: str,
        path: str,
        raw: str,
        *,
        query: dict[str, Any] | None = None,
        json_body: dict[str, Any] | None = None,
    ) -> str:
        ct = " ".join((content_type or "").split()) or "unknown"
        tmpl = _feishu_path_template(path)
        dynamic_ids = _feishu_request_dynamic_ids(path, query=query, json_body=json_body)
        preview = _sanitize_feishu_response_preview(
            raw,
            secrets=(self.app_secret, self._tenant_token),
            dynamic_ids=dynamic_ids,
            limit=120,
        )
        return f"http_{status} content_type={ct} path={tmpl} body={preview!r}"

    def _request(
        self,
        method: str,
        path: str,
        *,
        json_body: dict[str, Any] | None = None,
        query: dict[str, Any] | None = None,
        with_auth: bool = True,
        unwrap_data: bool = True,
    ) -> dict[str, Any]:
        url = f"{FEISHU_API_BASE}{path}"
        if query:
            cleaned_query = {k: v for k, v in query.items() if v is not None and v != ""}
            if cleaned_query:
                url = f"{url}?{urllib.parse.urlencode(cleaned_query)}"
        headers = {"Content-Type": "application/json"}
        if with_auth:
            headers["Authorization"] = f"Bearer {self._tenant_access_token()}"
        data_bytes = (
            json.dumps(json_body, ensure_ascii=False).encode("utf-8") if json_body is not None else None
        )
        req = urllib.request.Request(url, data=data_bytes, method=method, headers=headers)
        opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
        content_type = ""
        try:
            with opener.open(req, timeout=self.timeout_s) as resp:
                raw = resp.read().decode("utf-8", errors="replace")
                status = resp.status
                resp_headers = getattr(resp, "headers", None)
                if resp_headers is not None and hasattr(resp_headers, "get"):
                    content_type = str(
                        resp_headers.get("Content-Type") or resp_headers.get("content-type") or ""
                    )
        except urllib.error.HTTPError as exc:
            try:
                raw = exc.read().decode("utf-8", errors="replace")
            except Exception:
                raw = ""
            status = exc.code
            exc_headers = getattr(exc, "headers", None)
            if exc_headers is not None and hasattr(exc_headers, "get"):
                content_type = str(
                    exc_headers.get("Content-Type") or exc_headers.get("content-type") or ""
                )
        except Exception as exc:
            raise FeishuApiError("feishu_network_error", type(exc).__name__) from exc
        if status >= 500 and not raw.strip():
            # A server error with no body says nothing about whether the request
            # took effect (an empty gateway 502 after a committed write). An
            # empty 4xx is still a refusal and keeps its feishu_http_4xx code.
            raise FeishuApiError("feishu_empty_error_response", f"http_{status}")
        try:
            payload = json.loads(raw) if raw.strip() else {}
        except ValueError:
            raise FeishuApiError(
                "feishu_invalid_response",
                self._invalid_response_detail(
                    status, content_type, path, raw, query=query, json_body=json_body
                ),
            ) from None
        if not isinstance(payload, dict):
            raise FeishuApiError(
                "feishu_invalid_response",
                self._invalid_response_detail(
                    status, content_type, path, raw, query=query, json_body=json_body
                ),
            )
        if status < 200 or status >= 300:
            feishu_code, feishu_msg, log_id = _feishu_error_payload_ids(payload)
            raise FeishuApiError(
                f"feishu_http_{status}",
                f"code={payload.get('code')} msg={str(payload.get('msg') or '')[:200]}",
                feishu_code=feishu_code,
                feishu_msg=feishu_msg,
                log_id=log_id,
            )
        code = payload.get("code")
        if code not in (0, None):
            raise FeishuApiError(
                "feishu_api_error",
                f"code={code} msg={str(payload.get('msg') or '')[:200]}",
                feishu_code=str(code)[:32],
                feishu_msg=str(payload.get("msg") or "")[:200],
                log_id=_log_redaction.clean_log_field(
                    payload.get("log_id") or payload.get("request_id") or "", max_len=64
                ),
            )
        if not unwrap_data:
            # Some endpoints (tenant_access_token) carry their fields at the
            # top level instead of under `data`.
            return payload
        return payload.get("data") if isinstance(payload.get("data"), dict) else {}

    # -- im --

    def list_bot_chats(
        self, *, page_size: int = 100, max_pages: int = 10
    ) -> list[dict[str, Any]]:
        """The chats the bot itself is in (``im/v1/chats``), paginated.

        Only ``chat_id`` and ``name`` leave this method: the response's other
        fields (owner ids, member counts, descriptions) are not this feature's
        to expose.
        """
        chats: list[dict[str, Any]] = []
        page_token: str | None = None
        for _ in range(max_pages):
            data = self._request(
                "GET",
                "/open-apis/im/v1/chats",
                query={"page_size": page_size, "page_token": page_token},
            )
            items = data.get("items")
            if isinstance(items, list):
                for item in items:
                    if not isinstance(item, dict):
                        continue
                    chat_id = str(item.get("chat_id") or "").strip()
                    if chat_id:
                        chats.append(
                            {"chat_id": chat_id, "name": str(item.get("name") or "")}
                        )
            if not data.get("has_more"):
                break
            page_token = data.get("page_token") or None
            if not page_token:
                break
        return chats

    def bot_info(self) -> str:
        """The bot's own display name (``bot/v3/info``), nothing else.

        That endpoint nests its payload under a top-level ``bot`` key instead
        of the usual ``data`` (hence ``unwrap_data=False``), and carries ids
        beside the name — only the name leaves this method.
        """
        payload = self._request("GET", "/open-apis/bot/v3/info", unwrap_data=False)
        bot = payload.get("bot") if isinstance(payload.get("bot"), dict) else {}
        return str(bot.get("app_name") or "").strip()

    # -- docx --

    def get_document(self, document_id: str) -> dict[str, Any]:
        data = self._request("GET", f"/open-apis/docx/v1/documents/{document_id}")
        return data.get("document") if isinstance(data.get("document"), dict) else {}

    def raw_content(self, document_id: str) -> str:
        data = self._request(
            "GET", f"/open-apis/docx/v1/documents/{document_id}/raw_content"
        )
        return str(data.get("content") or "")

    def create_document(self, title: str, folder_token: str = "") -> dict[str, Any]:
        body: dict[str, Any] = {"title": title}
        if folder_token:
            body["folder_token"] = folder_token
        data = self._request("POST", "/open-apis/docx/v1/documents", json_body=body)
        return data.get("document") if isinstance(data.get("document"), dict) else {}

    def convert_markdown(self, markdown: str) -> tuple[list[str], list[dict[str, Any]]]:
        """Return ``(first_level_block_ids, blocks)`` from markdown conversion.

        The descendant-insert API needs both: ``children_id`` (the top-level
        ids) and ``descendants`` (the full block definitions) — submitting only
        the ids inserts nothing.
        """
        data = self._request(
            "POST",
            "/open-apis/docx/v1/documents/blocks/convert",
            json_body={"content_type": "markdown", "content": markdown},
        )
        ids = data.get("first_level_block_ids")
        blocks = data.get("blocks")
        return (
            [str(i) for i in ids] if isinstance(ids, list) else [],
            [b for b in blocks if isinstance(b, dict)] if isinstance(blocks, list) else [],
        )

    def insert_descendants(
        self,
        document_id: str,
        block_id: str,
        children_ids: list[str],
        descendants: list[dict[str, Any]],
        index: int,
    ) -> dict[str, Any]:
        return self._request(
            "POST",
            f"/open-apis/docx/v1/documents/{document_id}/blocks/{block_id}/descendant",
            json_body={
                "children_id": children_ids,
                "descendants": [_sanitize_feishu_block(b) for b in descendants],
                "index": index,
            },
        )

    def replace_block_image(
        self, document_id: str, block_id: str, file_token: str
    ) -> dict[str, Any]:
        """Bind an uploaded media ``file_token`` onto a docx image block via ``PATCH``."""
        return self._request(
            "PATCH",
            f"/open-apis/docx/v1/documents/{document_id}/blocks/{block_id}",
            json_body={"replace_image": {"token": file_token}},
        )

    def root_children_count(self, document_id: str) -> int:
        """Count the document root block's direct children (insert index for appends)."""
        total = 0
        page_token: str | None = None
        for _ in range(FEISHU_MAX_PAGES):
            data = self._request(
                "GET",
                f"/open-apis/docx/v1/documents/{document_id}/blocks/{document_id}/children",
                query={"page_size": FEISHU_PAGE_SIZE, "page_token": page_token},
            )
            items = data.get("items")
            total += len(items) if isinstance(items, list) else 0
            page_token = data.get("page_token") or None
            if not data.get("has_more") or not page_token:
                break
        return total

    def list_blocks(self, document_id: str) -> list[dict[str, Any]]:
        """The document's full flat block list (id, block_type, image token …)."""
        blocks: list[dict[str, Any]] = []
        page_token: str | None = None
        for _ in range(FEISHU_MAX_PAGES):
            data = self._request(
                "GET",
                f"/open-apis/docx/v1/documents/{document_id}/blocks",
                query={"page_size": FEISHU_PAGE_SIZE, "page_token": page_token},
            )
            items = data.get("items")
            if isinstance(items, list):
                blocks.extend(b for b in items if isinstance(b, dict))
            page_token = data.get("page_token") or None
            if not data.get("has_more") or not page_token:
                break
        return blocks

    def get_block(self, document_id: str, block_id: str) -> dict[str, Any]:
        data = self._request(
            "GET", f"/open-apis/docx/v1/documents/{document_id}/blocks/{block_id}"
        )
        return data.get("block") if isinstance(data.get("block"), dict) else {}

    def upload_docx_image(
        self,
        *,
        document_id: str,
        image_block_id: str,
        filename: str,
        data: bytes,
    ) -> str:
        """Upload image bytes as a docx image asset; returns the ``file_token``.

        ``medias/upload_all`` with ``parent_type=docx_image``. The 素材概述
        doc names the *image block's* id as the upload point for a docx
        image; where an app's scope rejects that, the caller retries with
        the document id — both spellings are tried by the binding flow, and
        whichever the live API accepts is the one that matters.
        """
        if not data:
            raise FeishuApiError("image_empty")
        if len(data) > FEISHU_IMAGE_MAX_BYTES:
            raise FeishuApiError("image_too_large", f"{len(data)} bytes")

        boundary = f"----daltonbridge{uuid.uuid4().hex}"
        fields: list[tuple[str, str]] = [
            ("file_name", filename),
            ("parent_type", "docx_image"),
            ("parent_node", image_block_id),
            # C2: the 素材上传 doc requires `extra` for docx_image uploads —
            # the docx route token the asset belongs to.
            ("extra", json.dumps({"drive_route_token": document_id})),
            ("size", str(len(data))),
        ]
        body = io.BytesIO()
        for name, value in fields:
            body.write(
                (
                    f"--{boundary}\r\n"
                    f'Content-Disposition: form-data; name="{name}"\r\n\r\n'
                    f"{value}\r\n"
                ).encode("utf-8")
            )
        body.write(
            (
                f"--{boundary}\r\n"
                f'Content-Disposition: form-data; name="file"; filename="{filename}"\r\n'
                f"Content-Type: application/octet-stream\r\n\r\n"
            ).encode("utf-8")
        )
        body.write(data)
        body.write(f"\r\n--{boundary}--\r\n".encode("utf-8"))
        payload_bytes = body.getvalue()

        url = f"{FEISHU_API_BASE}/open-apis/drive/v1/medias/upload_all"
        req = urllib.request.Request(
            url,
            data=payload_bytes,
            method="POST",
            headers={
                "Authorization": f"Bearer {self._tenant_access_token()}",
                "Content-Type": f"multipart/form-data; boundary={boundary}",
            },
        )
        opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
        raw = ""
        status = 0
        try:
            with opener.open(req, timeout=self.timeout_s) as resp:
                raw = resp.read().decode("utf-8", errors="replace")
                status = resp.status
        except urllib.error.HTTPError as exc:
            try:
                raw = exc.read().decode("utf-8", errors="replace")
            except Exception:
                raw = ""
            status = exc.code
        except Exception as exc:
            raise FeishuApiError("feishu_network_error", type(exc).__name__) from exc
        try:
            parsed = json.loads(raw) if raw.strip() else {}
        except ValueError:
            raise FeishuApiError(
                "feishu_invalid_response",
                self._invalid_response_detail(
                    status, "multipart", "/open-apis/drive/v1/medias/upload_all", raw
                ),
            ) from None
        if not isinstance(parsed, dict) or parsed.get("code") not in (0, None) or not (
            200 <= status < 300
        ):
            raise FeishuApiError(
                f"feishu_http_{status}" if not (200 <= status < 300) else "feishu_api_error",
                f"code={parsed.get('code')} msg={str(parsed.get('msg') or '')[:200]}",
            )
        data_obj = parsed.get("data") if isinstance(parsed.get("data"), dict) else {}
        file_token = str(data_obj.get("file_token") or "")
        if not file_token:
            raise FeishuApiError("image_upload_no_token")
        return file_token

    # -- wiki --

    def get_node(self, token: str, *, obj_type: str = "") -> dict[str, Any]:
        data = self._request(
            "GET",
            "/open-apis/wiki/v2/spaces/get_node",
            query={"token": token, "obj_type": obj_type},
        )
        return data.get("node") if isinstance(data.get("node"), dict) else {}

    def list_spaces(self) -> list[dict[str, Any]]:
        spaces: list[dict[str, Any]] = []
        page_token: str | None = None
        for _ in range(FEISHU_MAX_PAGES):
            data = self._request(
                "GET",
                "/open-apis/wiki/v2/spaces",
                query={"page_size": FEISHU_PAGE_SIZE, "page_token": page_token},
            )
            items = data.get("items")
            if isinstance(items, list):
                spaces.extend(i for i in items if isinstance(i, dict))
            page_token = data.get("page_token") or None
            if not data.get("has_more") or not page_token:
                break
        return spaces

    def list_nodes(self, space_id: str, parent_node_token: str = "") -> list[dict[str, Any]]:
        nodes: list[dict[str, Any]] = []
        page_token: str | None = None
        for _ in range(FEISHU_MAX_PAGES):
            data = self._request(
                "GET",
                f"/open-apis/wiki/v2/spaces/{space_id}/nodes",
                query={
                    "page_size": FEISHU_PAGE_SIZE,
                    "parent_node_token": parent_node_token,
                    "page_token": page_token,
                },
            )
            items = data.get("items")
            if isinstance(items, list):
                nodes.extend(i for i in items if isinstance(i, dict))
            page_token = data.get("page_token") or None
            if not data.get("has_more") or not page_token:
                break
        return nodes

    def create_wiki_doc(
        self, space_id: str, title: str, parent_node_token: str = ""
    ) -> dict[str, Any]:
        body: dict[str, Any] = {"obj_type": "docx", "title": title}
        if parent_node_token:
            body["parent_node_token"] = parent_node_token
        data = self._request(
            "POST", f"/open-apis/wiki/v2/spaces/{space_id}/nodes", json_body=body
        )
        return data.get("node") if isinstance(data.get("node"), dict) else {}

    # -- drive permissions --

    #: Feishu's own msg wording when a permission grant refuses the member's
    #: *identity* — the one refusal class that says the other member spelling
    #: could succeed. Matched on the payload msg, EN or CN.
    _FEISHU_MEMBER_NOT_EXIST_RE = re.compile(
        r"(?i)(?:user|member|account)\s+not\s+(?:exist|found)"
        r"|用户不存在|成员不存在|账号不存在"
    )

    #: Business codes verified as permission-class refusals. Currently empty
    #: on purpose: the only business code production ever showed on this call
    #: (1063001, HTTP 400, "Invalid parameter", 2026-10-28) is a parameter
    #: refusal, and no code has verified evidence of meaning permission — an
    #: unverified mapping would misroute the fallback, so a code lands here
    #: only with production proof.
    _FEISHU_GRANT_PERMISSION_CODES: frozenset[str] = frozenset()

    #: Refusal classes that may retry the grant with the email spelling.
    _FEISHU_GRANT_FALLBACK_CLASSES: frozenset[str] = frozenset({"identity"})

    @classmethod
    def _grant_refusal_class(cls, exc: "FeishuApiError") -> str:
        """Classify an openid-grant refusal for the email-fallback decision.

        The bridge has no vendor error table, so this is a conservative
        partition, not a Feishu code map, and every unclassifiable refusal
        lands in a class that does NOT fall back — an unknown error surfaces
        as itself instead of being masked by a second attempt.

        Order matters, and identity comes before the HTTP-shape classes:
        Feishu answers business refusals — member-not-exist included — as
        HTTP 400 with a body code/msg, so a 400-first order would file every
        identity refusal under parameter and the email fallback would be
        dead code. Identity matches only Feishu's own ``feishu_msg``, never
        the bridge-wrapped message text, so this classifier's own wording
        can never re-classify itself.

        * ``transport`` — `_feishu_outcome_unknown` (network, unparseable or
          empty body, 5xx): no definite verdict, and a retry could
          double-commit a write whose outcome is unknown.
        * ``identity`` — Feishu's own msg names the member as not existing
          (EN or CN): the one class that says the email spelling might
          succeed.
        * ``permission`` — HTTP 401/403, or a business code in the verified
          permission set: operator / app permission; both spellings hit the
          same wall.
        * ``parameter`` — any other HTTP 400: the request shape was refused;
          the email body has the same shape and fails the same way.
        * ``unclassified`` — anything else (including every numeric business
          code the bridge cannot positively name).
        """
        if _feishu_outcome_unknown(exc.error_code):
            return "transport"
        if cls._FEISHU_MEMBER_NOT_EXIST_RE.search(exc.feishu_msg):
            return "identity"
        if exc.error_code in ("feishu_http_401", "feishu_http_403"):
            return "permission"
        if exc.feishu_code in cls._FEISHU_GRANT_PERMISSION_CODES:
            return "permission"
        if exc.error_code == "feishu_http_400":
            return "parameter"
        return "unclassified"

    def _grant_phase(
        self,
        stage: str,
        *,
        status: str,
        exc: "FeishuApiError | None" = None,
        note: str = "",
        member_ids: tuple[str, ...] = (),
    ) -> dict[str, str]:
        """One grant stage's result, sanitized once for both the log line and
        the wire payload: the bridge error_code, Feishu's own code/msg, and
        the request log_id when the stage reached a payload. ``stage`` is
        ``lookup`` / ``openid`` / ``email``; ``status`` is ``ok`` / ``failed``
        / ``skipped``. Member identifiers (email, open_id) never enter a
        phase by construction, and a msg that echoes the member_id is
        scrubbed via ``member_ids`` (R7 r2, codex #1).

        R7 r3 (codex #2): when the failure never reached a payload msg
        (non-JSON response, network exception), ``feishu_msg`` is empty and
        the bridge's own exception text — `_request`'s HTTP status /
        content-type / path template / body preview, or the exception type —
        is the only diagnosis there was. It is kept in ``detail`` under the
        same scrubbing; empty whenever ``feishu_msg`` already says it."""
        phase: dict[str, str] = {"stage": stage, "status": status, "note": note}
        # The client's own credentials are scrubbed by value as well as by shape.
        member_ids = (*member_ids, self.app_secret, self._tenant_token)
        if exc is not None:
            phase["error_code"] = exc.error_code
            phase["feishu_code"] = _log_redaction.clean_log_field(exc.feishu_code, max_len=32)
            phase["feishu_msg"] = _feishu_scrub_member_text(exc.feishu_msg, member_ids)
            phase["detail"] = (
                ""
                if exc.feishu_msg
                else _feishu_scrub_member_text(str(exc), member_ids, max_len=160)
            )
            phase["log_id"] = _log_redaction.clean_log_field(exc.log_id, max_len=64)
        else:
            phase["error_code"] = ""
            phase["feishu_code"] = ""
            phase["feishu_msg"] = ""
            phase["detail"] = ""
            phase["log_id"] = ""
        return phase

    @staticmethod
    def _grant_phases_summary(phases: list[dict[str, str]]) -> str:
        """The phase list as one sanitized line: ``lookup:ok (found) |
        openid:failed feishu_http_403 feishu_code=1063001 msg=… log_id=…``."""
        parts: list[str] = []
        for phase in phases:
            bits = [f"{phase['stage']}:{phase['status']}"]
            if phase.get("error_code"):
                bits.append(phase["error_code"])
            if phase.get("feishu_code"):
                bits.append(f"feishu_code={phase['feishu_code']}")
            if phase.get("feishu_msg"):
                bits.append(f"msg={phase['feishu_msg']}")
            if phase.get("detail"):
                bits.append(f"detail={phase['detail']}")
            if phase.get("log_id"):
                bits.append(f"log_id={phase['log_id']}")
            if phase.get("note"):
                bits.append(f"({phase['note']})")
            parts.append(" ".join(bits))
        return " | ".join(parts)

    def user_open_id_by_email(self, email: str) -> str:
        """The Feishu ``open_id`` for *email*, via the directory's own
        batch-get-id lookup; ``''`` when the app cannot look (no contact
        scope) or the email matches no account.

        The endpoint is ``POST /open-apis/contact/v3/users/batch_get_id``
        with ``user_id_type=open_id`` and a JSON body ``{"emails": [...]}``;
        the answer's ``data.user_list[]`` carries one entry per queried
        address, ``{"email": ..., "user_id": <open_id>}`` — an unmatched
        address comes back with an empty ``user_id``.

        C1: an email grant 400s when the address is not a Feishu login
        email, while an open_id grant names the account itself — so the id
        lookup is the primary spelling and the email form only the
        fallback.
        """
        data = self._request(
            "POST",
            "/open-apis/contact/v3/users/batch_get_id",
            query={"user_id_type": "open_id"},
            json_body={"emails": [email]},
        )
        user_list = data.get("user_list")
        if isinstance(user_list, list):
            for item in user_list:
                if not isinstance(item, dict):
                    continue
                if str(item.get("email") or "").strip().lower() != email.strip().lower():
                    continue
                open_id = str(item.get("user_id") or "")
                if open_id:
                    return open_id
        return ""

    def grant_chat_full_access(self, token: str, chat_id: str) -> None:
        self._request(
            "POST",
            f"/open-apis/drive/v1/permissions/{token}/members",
            query={"type": "docx", "need_notification": "false"},
            json_body={
                "member_type": "openchat",
                "member_id": chat_id,
                "perm": "full_access",
            },
        )

    def grant_full_access(self, token: str, email: str = "", open_id: str = "") -> str:
        """Grant *email* / *open_id* full access; returns the member spelling that worked.

        Thin wrapper over `grant_full_access_with_phases` for callers that
        only need the spelling; see there for the staged grant contract.
        """
        if open_id:
            spelling, _phases = self.grant_full_access_with_phases(
                token, email, open_id=open_id
            )
        else:
            spelling, _phases = self.grant_full_access_with_phases(token, email)
        return spelling

    def grant_full_access_with_phases(
        self, token: str, email: str = "", open_id: str = ""
    ) -> tuple[str, list[dict[str, str]]]:
        """Grant *email* / *open_id* full access; returns ``(member spelling, phases)``.

        When a valid ``open_id`` is supplied (DALTON-HOOK(feishu-docs)), grant
        with it first (stage ``bound_openid``) and return immediately on success
        without hitting the email directory lookup. On failure, fall back to
        the existing three-stage email flow (``lookup`` -> ``openid`` ->
        ``email``) only when the refusal class is in
        ``_FEISHU_GRANT_FALLBACK_CLASSES`` (and an email is available);
        otherwise fail immediately. When ``open_id`` is omitted or malformed,
        behavior matches the existing three-stage email flow.
        """
        bound_open_id = _normalize_feishu_open_id(open_id)
        if not bound_open_id and not email:
            raise FeishuApiError("feishu_grant_failed", "no grant member", phases=[])
        phases: list[dict[str, str]] = []
        member_ids: tuple[str, ...] = tuple(m for m in (email, bound_open_id) if m)

        def _masked_member() -> str:
            # Unified log redaction + bridge-local open_id scrubbing: neither
            # the email address nor the open_id ever enters a log line.
            return _feishu_scrub_member_text(
                email or bound_open_id, member_ids, max_len=64
            )

        def _fail(cause: FeishuApiError) -> FeishuApiError:
            summary = self._grant_phases_summary(phases)
            logger.warning(
                "feishu_grant outcome=failed member=%s stages=%s", _masked_member(), summary
            )
            return FeishuApiError("feishu_grant_failed", summary, phases=phases)

        if bound_open_id:
            try:
                self._request(
                    "POST",
                    f"/open-apis/drive/v1/permissions/{token}/members",
                    query={"type": "docx", "need_notification": "false"},
                    json_body={
                        "member_type": "openid",
                        "member_id": bound_open_id,
                        "perm": "full_access",
                    },
                )
            except FeishuApiError as exc:
                refusal_class = self._grant_refusal_class(exc)
                phases.append(
                    self._grant_phase(
                        "bound_openid",
                        status="failed",
                        exc=exc,
                        note=f"class={refusal_class}",
                        member_ids=member_ids,
                    )
                )
                if refusal_class not in self._FEISHU_GRANT_FALLBACK_CLASSES or not email:
                    raise _fail(exc) from exc
            else:
                phases.append(self._grant_phase("bound_openid", status="ok"))
                logger.info(
                    "feishu_grant outcome=ok member=%s stages=%s",
                    _masked_member(),
                    self._grant_phases_summary(phases),
                )
                return "openid", phases

        try:
            looked_up_open_id = self.user_open_id_by_email(email)
        except FeishuApiError as exc:
            # A failed lookup is not "user not found" — the directory call
            # itself broke (scope / permission / transport), and an email
            # retry would mask which stage actually failed.
            phases.append(
                self._grant_phase("lookup", status="failed", exc=exc, member_ids=member_ids)
            )
            phases.append(
                self._grant_phase(
                    "email", status="skipped", note="no fallback: lookup itself failed"
                )
            )
            raise _fail(exc) from exc
        phases.append(
            self._grant_phase(
                "lookup", status="ok", note="not_found" if not looked_up_open_id else "found"
            )
        )
        if looked_up_open_id and looked_up_open_id not in member_ids:
            member_ids = (*member_ids, looked_up_open_id)

        if looked_up_open_id:
            try:
                self._request(
                    "POST",
                    f"/open-apis/drive/v1/permissions/{token}/members",
                    query={"type": "docx", "need_notification": "false"},
                    json_body={
                        "member_type": "openid",
                        "member_id": looked_up_open_id,
                        "perm": "full_access",
                    },
                )
            except FeishuApiError as exc:
                refusal_class = self._grant_refusal_class(exc)
                phases.append(
                    self._grant_phase(
                        "openid",
                        status="failed",
                        exc=exc,
                        note=f"class={refusal_class}",
                        member_ids=member_ids,
                    )
                )
                if refusal_class not in self._FEISHU_GRANT_FALLBACK_CLASSES:
                    phases.append(
                        self._grant_phase(
                            "email",
                            status="skipped",
                            note=f"no fallback: openid refusal class={refusal_class}",
                        )
                    )
                    raise _fail(exc) from exc
                # An identity refusal is the one verdict the email spelling
                # can change — it gets its own chance, and its own result.
            else:
                phases.append(self._grant_phase("openid", status="ok"))
                logger.info(
                    "feishu_grant outcome=ok member=%s stages=%s",
                    _masked_member(),
                    self._grant_phases_summary(phases),
                )
                return "openid", phases
        else:
            phases.append(
                self._grant_phase(
                    "openid", status="skipped", note="no fallback needed: lookup not_found"
                )
            )

        try:
            self._request(
                "POST",
                f"/open-apis/drive/v1/permissions/{token}/members",
                query={"type": "docx", "need_notification": "false"},
                json_body={
                    "member_type": "email",
                    "member_id": email,
                    "perm": "full_access",
                },
            )
        except FeishuApiError as exc:
            phases.append(
                self._grant_phase("email", status="failed", exc=exc, member_ids=member_ids)
            )
            raise _fail(exc) from exc
        phases.append(self._grant_phase("email", status="ok"))
        logger.info(
            "feishu_grant outcome=ok member=%s stages=%s",
            _masked_member(),
            self._grant_phases_summary(phases),
        )
        return f"email:{email}", phases


# ----------------------------------------------------------------------
# DALTON-HOOK(data-jobs): Standalone host task helpers (§2.3 item 3)
# ----------------------------------------------------------------------

HOST_TASK_GATE_FLAG = "--dalton-host-task-gate"
HOST_TASK_STATE_FILENAME = ".dalton-host-runner-state.json"
HOST_TASK_FENCE_LOST_FILENAME = ".dalton-host-runner-fence-lost"
HOST_TASK_MIN_SECRET_LEN = 4
HOST_TASK_REDACTED_PLACEHOLDER = "[REDACTED]"
HOST_TASK_EXIT_TOTAL_TIMEOUT = 124
HOST_TASK_EXIT_NO_OUTPUT_TIMEOUT = 125

BBG_REQUIRED_SERIES: dict[str, tuple[int, int]] = {
    "cyc_price": (0, 1),
    "cyc_rsi14": (3, 4),
    "momentum_rsi": (6, 7),
    "qqq_vol_1m": (9, 10),
    "qqq_vol_3m": (12, 13),
    "ah_price": (15, 16),
    "ah_rsi30": (18, 19),
}
BBG_MIN_LINES = 252
BBG_FORMULA_ERROR_RE = re.compile(r"#N/A|#REF!|#DIV/0!|#VALUE!|#NAME\?", re.IGNORECASE)


def _managed_host_secret_token_values() -> tuple[str, ...]:
    """Return non-empty management tokens from `os.environ` matching `src/dalton/settings.py:managed_secret_token_values`."""
    return tuple(
        t
        for t in (
            os.environ.get("DALTON_BRIDGE_ADMIN_TOKEN", "").strip(),
            os.environ.get("INTERNAL_SERVICE_TOKEN", "").strip(),
            os.environ.get("DALTON_TRANSCRIPTION_TICKET_SECRET", "").strip(),
            os.environ.get("DALTON_TRANSCRIPTION_TOKEN", "").strip(),
        )
        if t
    )


def _redact_host_managed_tokens(text: Any) -> Any:
    """Replace management token values with `***` matching `src/dalton/settings.py:redact_managed_tokens`."""
    if not isinstance(text, str):
        return text
    for token in _managed_host_secret_token_values():
        text = text.replace(token, "***")
    return text


def _collect_host_secret_strings(value: Any, out: set[str]) -> None:
    """Recursively collect non-empty string values of length >= 4 matching `runner_wrapper._collect_secret_strings`."""
    if isinstance(value, str):
        stripped = value.strip()
        if len(stripped) >= HOST_TASK_MIN_SECRET_LEN:
            out.add(stripped)
        if len(value) >= HOST_TASK_MIN_SECRET_LEN:
            out.add(value)
        if stripped.startswith(("{", "[")):
            try:
                parsed = json.loads(stripped)
            except Exception:
                return
            _collect_host_secret_strings(parsed, out)
    elif isinstance(value, Mapping):
        for v in value.values():
            _collect_host_secret_strings(v, out)
    elif isinstance(value, (list, tuple, set)):
        for item in value:
            _collect_host_secret_strings(item, out)


class HostSecretRedactor:
    """In-memory redactor matching `src/dalton/data_jobs/runner_wrapper.py:SecretRedactor` (§4.4.3)."""

    def __init__(self, secret_values: Any = ()) -> None:
        collected: set[str] = set()
        for raw in secret_values:
            _collect_host_secret_strings(raw, collected)
        for token in _managed_host_secret_token_values():
            if token:
                collected.add(token)
        self._patterns: tuple[str, ...] = tuple(
            sorted((s for s in collected if s), key=len, reverse=True)
        )

    @property
    def patterns(self) -> tuple[str, ...]:
        return self._patterns

    def redact_text(self, text: str) -> str:
        if not text:
            return text
        out = text
        for pattern in self._patterns:
            if pattern in out:
                out = out.replace(pattern, HOST_TASK_REDACTED_PLACEHOLDER)
        out = str(_redact_host_managed_tokens(out))
        return out

    def redact_value(self, obj: Any) -> Any:
        if isinstance(obj, str):
            return self.redact_text(obj)
        if isinstance(obj, Mapping):
            return {
                (self.redact_text(k) if isinstance(k, str) else k): self.redact_value(v)
                for k, v in obj.items()
            }
        if isinstance(obj, list):
            return [self.redact_value(item) for item in obj]
        if isinstance(obj, tuple):
            return tuple(self.redact_value(item) for item in obj)
        return obj


# DALTON-HOOK(host-job-secrets): mask Vault-injected host secrets with "***" in logs/tail/outbox
class _HostTaskVaultRedactor(HostSecretRedactor):
    """Mask host-task Vault secret values with `***` before applying `HostSecretRedactor`."""

    def __init__(self, vault_secret_values: Any = ()) -> None:
        super().__init__()
        vault_collected: set[str] = set()
        for raw in vault_secret_values:
            _collect_host_secret_strings(raw, vault_collected)
        self._vault_patterns: tuple[str, ...] = tuple(
            sorted((s for s in vault_collected if s), key=len, reverse=True)
        )

    def redact_text(self, text: str) -> str:
        if not text:
            return text
        out = text
        for pattern in self._vault_patterns:
            if pattern in out:
                out = out.replace(pattern, "***")
        return super().redact_text(out)


# DALTON-HOOK(host-job-secrets): host outbox staging dir & strict redaction/cleanup helpers
_HOST_OUTBOX_STAGING_PREFIX = ".dalton-outbox-"
# Well past the longest host task timeout (3 h), so a directory still in use by a
# live run (or another bridge/test process sharing this user's $TMPDIR) is never touched.
_HOST_OUTBOX_STALE_AGE_S = 12 * 3600
_HOST_OUTBOX_CLEANUP_EXTRA_DIRS: tuple[str, ...] = ("/dev/shm",)


def _cleanup_stale_host_outbox_staging_dirs(min_age_s: float = _HOST_OUTBOX_STALE_AGE_S) -> int:
    """Remove leftover `.dalton-outbox-*` dirs owned by the current user under `$TMPDIR` and `/dev/shm`.

    Runs only at bridge startup recovery; age-gated because `$TMPDIR` is shared with
    any other process of the same user.
    """
    candidates: list[Path] = []
    seen: set[str] = set()
    for raw_base in (tempfile.gettempdir(), *_HOST_OUTBOX_CLEANUP_EXTRA_DIRS):
        if not raw_base:
            continue
        norm = os.path.normpath(str(raw_base))
        if norm in seen:
            continue
        seen.add(norm)
        candidates.append(Path(norm))

    current_uid = os.getuid() if hasattr(os, "getuid") else None
    removed = 0
    for base in candidates:
        try:
            base_st = base.lstat()
        except OSError:
            continue
        if not stat.S_ISDIR(base_st.st_mode):
            continue
        try:
            with os.scandir(base) as it:
                for entry in it:
                    if not entry.name.startswith(_HOST_OUTBOX_STAGING_PREFIX):
                        continue
                    entry_path = Path(entry.path)
                    try:
                        est = entry_path.lstat()
                    except OSError:
                        continue
                    # Never follow symlinks and only touch directories owned by the current user.
                    if stat.S_ISLNK(est.st_mode) or not stat.S_ISDIR(est.st_mode):
                        continue
                    if current_uid is not None and est.st_uid != current_uid:
                        continue
                    if time.time() - est.st_mtime < min_age_s:
                        continue
                    shutil.rmtree(entry_path, ignore_errors=True)
                    removed += 1
        except OSError:
            continue
    return removed


def _create_host_outbox_staging_dir() -> Path:
    """Create a private `0700` staging directory for one host run's readable/appendable outbox."""
    shm_dir = Path("/dev/shm")
    use_shm = (
        os.name == "posix"
        and not shm_dir.is_symlink()
        and shm_dir.is_dir()
        and os.access(shm_dir, os.W_OK | os.X_OK)
    )
    if use_shm:
        staging_dir = Path(tempfile.mkdtemp(prefix=_HOST_OUTBOX_STAGING_PREFIX, dir=str(shm_dir)))
    else:
        staging_dir = Path(tempfile.mkdtemp(prefix=_HOST_OUTBOX_STAGING_PREFIX))
    os.chmod(staging_dir, 0o700)
    return staging_dir


def _finalize_host_run_outbox_file(
    staging_file: Path,
    final_outbox_path: Path,
    redactor: HostSecretRedactor,
) -> None:
    """Read `staging_file` into RAM, remove it immediately, redact strictly, and atomically write `final_outbox_path`."""
    if staging_file.is_symlink():
        try:
            staging_file.unlink()
        except OSError:
            pass
        raise RuntimeError("outbox_staging_symlink")
    if not staging_file.exists():
        return
    try:
        raw = staging_file.read_text(encoding="utf-8")
    finally:
        try:
            staging_file.unlink()
        except OSError:
            pass

    if not raw.strip():
        return

    parsed = json.loads(raw)
    scrubbed_obj = redactor.redact_value(parsed)
    scrubbed_json = json.dumps(scrubbed_obj, ensure_ascii=False, indent=2)
    vault_patterns = tuple(getattr(redactor, "_vault_patterns", ()))
    for pattern in vault_patterns:
        if pattern and pattern in scrubbed_json:
            raise RuntimeError("outbox_redaction_incomplete")

    final_outbox_path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp_name = tempfile.mkstemp(
        prefix=".outbox.",
        suffix=".tmp",
        dir=str(final_outbox_path.parent),
    )
    tmp_path = Path(tmp_name)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            fh.write(scrubbed_json)
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp_path, final_outbox_path)
    except Exception:
        try:
            if tmp_path.exists():
                tmp_path.unlink()
        except OSError:
            pass
        raise


def _normalize_lstart(val: Any) -> str:
    """Normalize a `ps -o lstart=` string by collapsing internal whitespace."""
    return " ".join(str(val or "").split())


def _list_host_processes_ps() -> list[tuple[int, int, str, str]] | None:
    """Run `ps -ww -x -o pid=,pgid=,lstart=,command=` and return `(pid, pgid, lstart, command)` tuples.

    Returns `None` if `ps` execution fails so callers treat process state as unconfirmed.
    """
    try:
        res = subprocess.run(
            ["ps", "-ww", "-x", "-o", "pid=,pgid=,lstart=,command="],
            capture_output=True,
            text=True,
            timeout=10,
            check=False,
            # LC_ALL=C: lstart is locale-formatted (zh_CN prints "四 11/15 …", four
            # tokens), and the split below needs the fixed five-token C form.
            env=bridge_subprocess_env.build_nonarchive_subprocess_env(
                dict(os.environ), extra_env={"LC_ALL": "C", "LANG": "C"}
            ),
        )
        if res.returncode != 0:
            return None
        rows: list[tuple[int, int, str, str]] = []
        for line in (res.stdout or "").splitlines():
            stripped = line.strip()
            if not stripped:
                continue
            # pid, pgid, 5 tokens of lstart (dow mon dom hh:mm:ss yyyy), command
            parts = stripped.split(None, 7)
            if len(parts) < 8:
                continue
            try:
                pid = int(parts[0])
                pgid = int(parts[1])
            except ValueError:
                continue
            lstart = " ".join(parts[2:7])
            command = parts[7]
            rows.append((pid, pgid, lstart, command))
        return rows
    except Exception:
        return None


def _normalize_ps_rows(raw_rows: Any) -> list[tuple[int, int, str, str]] | None:
    """Normalize process rows from `_list_host_processes_ps` into 4-tuples `(pid, pgid, lstart, command)`."""
    if raw_rows is None:
        return None
    normalized: list[tuple[int, int, str, str]] = []
    for item in raw_rows:
        if not isinstance(item, (tuple, list)):
            continue
        if len(item) >= 4:
            normalized.append(
                (int(item[0]), int(item[1]), _normalize_lstart(item[2]), str(item[3]))
            )
        elif len(item) == 3:
            normalized.append((int(item[0]), int(item[1]), "", str(item[2])))
    return normalized


def _get_process_leader_lstart_sync(
    pgid: int,
    *,
    ps_list_fn: Any = None,
) -> str | None:
    """Look up `lstart` for the process group leader (`pid == pgid`) via `ps`."""
    list_fn = ps_list_fn or _list_host_processes_ps
    rows = _normalize_ps_rows(list_fn())
    if rows is None:
        return None
    for pid, r_pgid, lstart, _cmd in rows:
        if pid == pgid and r_pgid == pgid and lstart:
            return lstart
    return None


def _reap_pgid_zombies(pgid: int) -> None:
    """Reap any zombie child processes belonging to `pgid` in the current process."""
    if pgid <= 0:
        return
    for target in (-pgid, pgid):
        for _ in range(8):
            try:
                wpid, _ = os.waitpid(target, os.WNOHANG)
                if wpid <= 0:
                    break
            except (ChildProcessError, PermissionError, OSError):
                break


def _is_fence_lost_dalton_task_command(command: str, *, data_root: Path | None = None) -> bool:
    """Match Dalton host-task commands by Dalton markers.

    Matches ONLY `--dalton-host-task-gate` or full paths under `<data_root>/scripts/`
    (`bbg_remote_refresh.sh`, `bbg_export_to_csv.py`), never bare script names.
    """
    if HOST_TASK_GATE_FLAG in command:
        return True
    if data_root is None:
        return False
    scripts_dir = Path(data_root) / "scripts"
    return (
        str(scripts_dir / "bbg_remote_refresh.sh") in command
        or str(scripts_dir / "bbg_export_to_csv.py") in command
    )


def _scan_and_stop_fence_lost_pgids_sync(
    data_root: Path,
    *,
    active_runs: dict[int, dict[str, Any]] | None = None,
    sigterm_grace_s: float = 5.0,
    sigkill_wait_s: float = 2.0,
    ps_list_fn: Any = None,
) -> tuple[list[int], list[int], dict[int, dict[str, Any]], bool]:
    """Scan process table on `fence_lost`, merge with recorded `active_runs`, and stop/verify Dalton task groups."""
    list_fn = ps_list_fn or _list_host_processes_ps
    merged_active: dict[int, dict[str, Any]] = {}
    for raw_k, raw_v in (active_runs or {}).items():
        if isinstance(raw_v, dict):
            p_val = raw_v.get("pgid", raw_k)
            lstart_raw = raw_v.get("lstart")
            norm_lstart = _normalize_lstart(lstart_raw) if isinstance(lstart_raw, str) else None
            if isinstance(p_val, int) and not isinstance(p_val, bool) and p_val > 0:
                merged_active[int(p_val)] = {
                    "pgid": int(p_val),
                    "lstart": norm_lstart if norm_lstart else None,
                }
        elif isinstance(raw_k, int) and not isinstance(raw_k, bool) and raw_k > 0:
            merged_active[int(raw_k)] = {"pgid": int(raw_k), "lstart": None}

    rows = _normalize_ps_rows(list_fn())
    if rows is None:
        return [], sorted(merged_active.keys()), merged_active, False

    self_pid = os.getpid()
    leaders_by_pgid: dict[int, str] = {}
    for pid, r_pgid, lstart, _cmd in rows:
        if r_pgid > 0 and pid == r_pgid and pid != self_pid:
            leaders_by_pgid[r_pgid] = lstart

    scanned_pgids = sorted(
        {
            r_pgid
            for (pid, r_pgid, _lstart, cmd) in rows
            if r_pgid > 0
            and pid != self_pid
            and _is_fence_lost_dalton_task_command(cmd, data_root=data_root)
        }
    )
    for p in scanned_pgids:
        if p not in merged_active:
            merged_active[p] = {
                "pgid": p,
                "lstart": leaders_by_pgid.get(p),
            }

    if not merged_active:
        return [], [], {}, True

    stopped, remaining = _stop_and_verify_host_pgids_sync(
        merged_active,
        data_root=data_root,
        sigterm_grace_s=sigterm_grace_s,
        sigkill_wait_s=sigkill_wait_s,
        ps_list_fn=list_fn,
    )
    remaining_set = set(remaining)
    remaining_active = {
        p: info for p, info in sorted(merged_active.items()) if p in remaining_set
    }
    return stopped, remaining, remaining_active, len(remaining) == 0


def _stop_and_verify_host_pgids_sync(
    targets: Any,
    *,
    data_root: Path | None = None,
    sigterm_grace_s: float = 5.0,
    sigkill_wait_s: float = 2.0,
    ps_list_fn: Any = None,
) -> tuple[list[int], list[int]]:
    """Verify process identity via `ps -ww -x -o pid=,pgid=,lstart=,command=` and stop process groups.

    - Identity check before signaling:
      1. Group leader (`pid == pgid`) present and `lstart` matches recorded `lstart`:
         Dalton's group -> stop and confirm.
      2. Group leader present and `lstart` does not match recorded `lstart` (or no `lstart`
         was recorded and the leader command lacks Dalton markers):
         `pgid` was reused -> do NOT signal; mark stopped so caller removes stale record, and log warning.
      3. Group leader absent (`pid == pgid` not in `ps`) and group still has processes:
         ONLY if at least one member in the group has a Dalton marker (`--dalton-host-task-gate`,
         or `<data_root>/scripts/bbg_remote_refresh.sh` / `<data_root>/scripts/bbg_export_to_csv.py`)
         do we signal and wait for the entire group to exit; otherwise do NOT signal, keep unconfirmed
         (`remaining`), and log an ERROR with `pgid` and member command lines for manual intervention.
      4. Group leader absent and group has no processes:
         Already stopped.
    - Exit confirmation:
      Once signaled, as long as ANY process in `ps` still has `pgid` equal to this group
      (regardless of command line), it is not considered exited; after `sigterm_grace_s`,
      `SIGKILL` is sent to the group; only when the entire group disappears is it confirmed.
    - If `ps` fails (`None`), treats the group as unconfirmed (`remaining_pgids`).
    """
    list_fn = ps_list_fn or _list_host_processes_ps
    normalized_targets: list[tuple[int, str]] = []
    seen_pgids: set[int] = set()
    iterable_targets = targets.values() if isinstance(targets, dict) else (targets or [])
    for item in iterable_targets:
        if isinstance(item, dict):
            raw_pgid = item.get("pgid")
            raw_lstart = _normalize_lstart(item.get("lstart"))
        else:
            raw_pgid = item
            raw_lstart = ""
        if isinstance(raw_pgid, int) and not isinstance(raw_pgid, bool) and raw_pgid > 0:
            if raw_pgid not in seen_pgids:
                seen_pgids.add(raw_pgid)
                normalized_targets.append((raw_pgid, raw_lstart))

    if not normalized_targets:
        return [], []

    self_pid = os.getpid()
    stopped: list[int] = []
    remaining: list[int] = []

    for pgid, expected_lstart in normalized_targets:
        _reap_pgid_zombies(pgid)
        rows = _normalize_ps_rows(list_fn())
        if rows is None:
            remaining.append(pgid)
            continue

        group_rows = [
            (pid, r_pgid, lstart, cmd)
            for (pid, r_pgid, lstart, cmd) in rows
            if r_pgid == pgid and pid != self_pid
        ]
        if not group_rows:
            stopped.append(pgid)
            continue

        leader_rows = [
            (pid, r_pgid, lstart, cmd)
            for (pid, r_pgid, lstart, cmd) in group_rows
            if pid == pgid
        ]
        if leader_rows:
            leader_lstart, leader_cmd = leader_rows[0][2], leader_rows[0][3]
            if expected_lstart:
                if leader_lstart != expected_lstart:
                    logger.warning(
                        "Host task pgid=%s leader lstart mismatch (recorded=%r, current=%r); "
                        "skipping kill and dropping stale state entry",
                        pgid,
                        expected_lstart,
                        leader_lstart,
                    )
                    stopped.append(pgid)
                    continue
            else:
                has_dalton_marker = _is_fence_lost_dalton_task_command(
                    leader_cmd, data_root=data_root
                )
                if not has_dalton_marker:
                    logger.warning(
                        "Host task pgid=%s leader present without recorded lstart or Dalton marker (cmd=%r); "
                        "skipping kill and dropping stale state entry",
                        pgid,
                        leader_cmd,
                    )
                    stopped.append(pgid)
                    continue
        else:
            has_group_dalton_marker = any(
                _is_fence_lost_dalton_task_command(cmd, data_root=data_root)
                for (_pid, _r_pgid, _lstart, cmd) in group_rows
            )
            if not has_group_dalton_marker:
                group_cmds = [cmd for (_pid, _r_pgid, _lstart, cmd) in group_rows]
                logger.error(
                    "Host task pgid=%s leader absent and no group member has Dalton marker (commands=%r); "
                    "not signaling and keeping unconfirmed for manual intervention",
                    pgid,
                    group_cmds,
                )
                remaining.append(pgid)
                continue

        try:
            os.killpg(pgid, signal.SIGTERM)
        except ProcessLookupError:
            pass
        except PermissionError:
            pass
        except OSError:
            pass

        ps_failed = False
        deadline = time.monotonic() + max(0.05, float(sigterm_grace_s))
        while time.monotonic() < deadline:
            _reap_pgid_zombies(pgid)
            cur_rows = _normalize_ps_rows(list_fn())
            if cur_rows is None:
                ps_failed = True
                break
            still_there = [
                (pid, r_pgid, lstart, cmd)
                for (pid, r_pgid, lstart, cmd) in cur_rows
                if r_pgid == pgid and pid != self_pid
            ]
            if not still_there:
                break
            time.sleep(0.05)

        if ps_failed:
            remaining.append(pgid)
            continue

        _reap_pgid_zombies(pgid)
        cur_rows = _normalize_ps_rows(list_fn())
        if cur_rows is None:
            remaining.append(pgid)
            continue

        still_there = [
            (pid, r_pgid, lstart, cmd)
            for (pid, r_pgid, lstart, cmd) in cur_rows
            if r_pgid == pgid and pid != self_pid
        ]
        if still_there:
            try:
                os.killpg(pgid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            except PermissionError:
                pass
            except OSError:
                pass

            kill_deadline = time.monotonic() + max(0.05, float(sigkill_wait_s))
            while time.monotonic() < kill_deadline:
                _reap_pgid_zombies(pgid)
                cur_rows = _normalize_ps_rows(list_fn())
                if cur_rows is None:
                    ps_failed = True
                    break
                still_there = [
                    (pid, r_pgid, lstart, cmd)
                    for (pid, r_pgid, lstart, cmd) in cur_rows
                    if r_pgid == pgid and pid != self_pid
                ]
                if not still_there:
                    break
                time.sleep(0.05)

        if ps_failed:
            remaining.append(pgid)
            continue

        _reap_pgid_zombies(pgid)
        final_rows = _normalize_ps_rows(list_fn())
        if final_rows is None:
            remaining.append(pgid)
            continue
        final_matching = [
            (pid, r_pgid, lstart, cmd)
            for (pid, r_pgid, lstart, cmd) in final_rows
            if r_pgid == pgid and pid != self_pid
        ]
        if final_matching:
            remaining.append(pgid)
        else:
            stopped.append(pgid)

    return stopped, remaining


async def _stream_and_wait_host_proc(
    *,
    proc: asyncio.subprocess.Process,
    pgid: int,
    leader_lstart: str | None = None,
    data_root: Path | None = None,
    redactor: HostSecretRedactor,
    timeout_s: float,
    no_output_timeout_s: float | None,
    sigterm_grace_s: float = 5.0,
    ps_list_fn: Any = None,
) -> tuple[int, bool, str | None, str, str]:
    """Stream and redact stdout/stderr in real time while enforcing total and no-output timeouts."""
    start_mono = time.monotonic()
    last_output_mono = start_mono
    max_secret_len = max((len(p) for p in redactor.patterns), default=0)
    tail_keep = max(0, max_secret_len - 1)
    stdout_chunks: list[str] = []
    stderr_chunks: list[str] = []

    async def _pump(stream: asyncio.StreamReader | None, sink: list[str]) -> None:
        nonlocal last_output_mono
        if stream is None:
            return
        pending = ""
        while True:
            chunk = await stream.read(4096)
            if not chunk:
                break
            last_output_mono = time.monotonic()
            decoded = chunk.decode("utf-8", errors="replace")
            combined = redactor.redact_text(pending + decoded)
            if tail_keep > 0 and len(combined) > tail_keep:
                flushed = combined[:-tail_keep]
                pending = combined[-tail_keep:]
                sink.append(flushed)
            elif tail_keep == 0:
                sink.append(combined)
                pending = ""
            else:
                pending = combined
        if pending:
            sink.append(redactor.redact_text(pending))

    pump_out = asyncio.create_task(_pump(proc.stdout, stdout_chunks))
    pump_err = asyncio.create_task(_pump(proc.stderr, stderr_chunks))
    wait_task = asyncio.create_task(proc.wait())

    timed_out = False
    timeout_kind: str | None = None
    try:
        while not wait_task.done():
            now = time.monotonic()
            elapsed = now - start_mono
            if elapsed >= timeout_s:
                timed_out = True
                timeout_kind = "total"
                break
            if no_output_timeout_s is not None and (now - last_output_mono) >= no_output_timeout_s:
                timed_out = True
                timeout_kind = "no_output"
                break
            remaining = timeout_s - elapsed
            if no_output_timeout_s is not None:
                remaining = min(remaining, no_output_timeout_s - (now - last_output_mono))
            sleep_step = max(0.02, min(0.25, remaining))
            done, _ = await asyncio.wait({wait_task}, timeout=sleep_step)
            if done:
                break

        if timed_out:
            await asyncio.to_thread(
                _stop_and_verify_host_pgids_sync,
                [{"pgid": pgid, "lstart": leader_lstart}],
                data_root=data_root,
                sigterm_grace_s=sigterm_grace_s,
                ps_list_fn=ps_list_fn,
            )
            try:
                await asyncio.wait_for(wait_task, timeout=2.0)
            except Exception:
                pass
    finally:
        for t in (pump_out, pump_err):
            try:
                await asyncio.wait_for(t, timeout=2.0)
            except Exception:
                t.cancel()
        if not wait_task.done():
            wait_task.cancel()

    if timed_out:
        exit_code = (
            HOST_TASK_EXIT_NO_OUTPUT_TIMEOUT
            if timeout_kind == "no_output"
            else HOST_TASK_EXIT_TOTAL_TIMEOUT
        )
    else:
        rc = proc.returncode
        exit_code = int(rc) if isinstance(rc, int) and not isinstance(rc, bool) else 1

    return (
        exit_code,
        timed_out,
        timeout_kind,
        "".join(stdout_chunks),
        "".join(stderr_chunks),
    )


def _parse_slot_utc_epoch(raw_slot: Any) -> float:
    """Parse `scheduled_slot_utc` (ISO-8601 string, datetime, or numeric epoch) into UTC epoch seconds."""
    if isinstance(raw_slot, (int, float)) and not isinstance(raw_slot, bool):
        return float(raw_slot)
    if isinstance(raw_slot, datetime):
        dt = raw_slot if raw_slot.tzinfo is not None else raw_slot.replace(tzinfo=timezone.utc)
        return dt.timestamp()
    text = str(raw_slot or "").strip()
    if not text:
        return 0.0
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    dt = datetime.fromisoformat(text)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.timestamp()


def validate_bbg_mirror_files(csv_path: Path, xlsx_path: Path) -> dict[str, Any]:
    """Validate staged BBG CSV and XLSX files before replacing existing files in `<data_root>/temp/` (§2.3 item 3).

    Column indices are hardcoded to match `.agy/oc1/openclaw/scripts/bbg_export_to_csv.py:30-38`:
    - `cyc_price`: (0, 1)
    - `cyc_rsi14`: (3, 4)
    - `momentum_rsi`: (6, 7)
    - `qqq_vol_1m`: (9, 10)
    - `qqq_vol_3m`: (12, 13)
    - `ah_price`: (15, 16)
    - `ah_rsi30`: (18, 19)
    Header row with fewer than 20 columns fails validation immediately; short data rows
    skip missing series columns and count only valid points per series (`bbg_export_to_csv.py:95-99`).
    """
    if not xlsx_path.is_file() or xlsx_path.stat().st_size == 0:
        return {"ok": False, "reason": "xlsx_missing_or_empty"}
    if not zipfile.is_zipfile(xlsx_path):
        return {"ok": False, "reason": "xlsx_not_valid_zip"}
    try:
        with zipfile.ZipFile(xlsx_path, "r") as zf:
            if not zf.namelist() or zf.testzip() is not None:
                return {"ok": False, "reason": "xlsx_corrupt_zip"}
    except Exception as exc:
        return {"ok": False, "reason": f"xlsx_zip_error:{type(exc).__name__}"}

    if not csv_path.is_file() or csv_path.stat().st_size == 0:
        return {"ok": False, "reason": "csv_missing_or_empty"}
    try:
        raw_text = csv_path.read_text(encoding="utf-8")
    except Exception as exc:
        return {"ok": False, "reason": f"csv_read_error:{type(exc).__name__}"}

    if BBG_FORMULA_ERROR_RE.search(raw_text):
        return {"ok": False, "reason": "csv_contains_formula_error"}

    lines_count = len(raw_text.splitlines())
    if lines_count < BBG_MIN_LINES:
        return {"ok": False, "reason": f"csv_lines_below_252:{lines_count}"}

    try:
        rows = list(csv.reader(io.StringIO(raw_text)))
    except Exception as exc:
        return {"ok": False, "reason": f"csv_parse_error:{type(exc).__name__}"}

    if len(rows) < 2:
        return {"ok": False, "reason": "csv_missing_data_rows"}

    header = [str(col).strip() for col in rows[0]]
    if len(header) < 20:
        return {"ok": False, "reason": f"csv_columns_below_20:{len(header)}"}

    data_rows = rows[1:]
    counts: dict[str, int] = {name: 0 for name in BBG_REQUIRED_SERIES}
    last_dates: dict[str, str] = {name: "" for name in BBG_REQUIRED_SERIES}

    for row in data_rows:
        for name, (d_col, v_col) in BBG_REQUIRED_SERIES.items():
            if len(row) <= v_col or len(row) <= d_col:
                continue
            d_str = str(row[d_col]).strip()
            v_str = str(row[v_col]).strip()
            if not d_str or not v_str or v_str == "None":
                continue
            try:
                num = float(v_str)
            except ValueError:
                continue
            if math.isnan(num) or math.isinf(num):
                continue
            counts[name] += 1
            if d_str >= last_dates[name]:
                last_dates[name] = d_str

    for name in BBG_REQUIRED_SERIES:
        if counts[name] < BBG_MIN_LINES:
            return {
                "ok": False,
                "reason": f"series_below_252:{name}:{counts[name]}",
                "counts": counts,
                "last_dates": last_dates,
            }

    return {
        "ok": True,
        "lines": lines_count,
        "counts": counts,
        "last_dates": last_dates,
    }


def _has_non_dalton_bbg_refresh_process(
    rows: list[tuple[int, int, str, str]] | list[tuple[int, int, str]],
    *,
    dalton_pgids: set[int],
    data_root: Path,
) -> bool:
    """Return True if any non-Dalton `bbg_remote_refresh.sh` process is running on the host."""
    norm_rows = _normalize_ps_rows(rows) or []
    data_root_str = str(data_root)
    for _pid, pgid, _lstart, cmd in norm_rows:
        if "bbg_remote_refresh.sh" not in cmd:
            continue
        if pgid in dalton_pgids:
            continue
        if HOST_TASK_GATE_FLAG in cmd or data_root_str in cmd:
            continue
        return True
    return False


def _stage_and_commit_bbg_mirror(
    *,
    ocw_root: Path,
    data_root: Path,
) -> tuple[int, str]:
    """Atomically stage and validate OpenClaw BBG CSV/XLSX into `<data_root>/temp/`."""
    src_csv = ocw_root / "temp" / "bbg_data_latest.csv"
    src_xlsx = ocw_root / "temp" / "bbg_data_remote.xlsx"
    dst_dir = data_root / "temp"
    dst_dir.mkdir(parents=True, exist_ok=True)
    dst_csv = dst_dir / "bbg_data_latest.csv"
    dst_xlsx = dst_dir / "bbg_data_remote.xlsx"

    if not src_csv.is_file() or not src_xlsx.is_file():
        err_out = {
            "ok": False,
            "error": "source_files_missing",
            "reason": "source_files_missing",
            "source": "openclaw_mirror",
        }
        return 1, json.dumps(err_out, ensure_ascii=False) + "\n"

    tag = f"{os.getpid()}.{uuid.uuid4().hex[:8]}"
    tmp_csv = dst_dir / f".bbg_data_latest.csv.{tag}.tmp"
    tmp_xlsx = dst_dir / f".bbg_data_remote.xlsx.{tag}.tmp"
    try:
        shutil.copy2(src_csv, tmp_csv)
        shutil.copy2(src_xlsx, tmp_xlsx)
        verdict = validate_bbg_mirror_files(tmp_csv, tmp_xlsx)
        if not verdict.get("ok"):
            tmp_csv.unlink(missing_ok=True)
            tmp_xlsx.unlink(missing_ok=True)
            reason = str(verdict.get("reason") or "validation_failed")
            err_out = {
                "ok": False,
                "error": reason,
                "reason": reason,
                "source": "openclaw_mirror",
            }
            return 1, json.dumps(err_out, ensure_ascii=False) + "\n"

        os.replace(tmp_xlsx, dst_xlsx)
        os.replace(tmp_csv, dst_csv)
        out = {
            "ok": True,
            "lines": int(verdict["lines"]),
            "source": "openclaw_mirror",
            "path": str(dst_csv),
            "timestamp": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
            "detail": {
                "counts": verdict["counts"],
                "last_dates": verdict["last_dates"],
            },
        }
        return 0, json.dumps(out, ensure_ascii=False) + "\n"
    finally:
        tmp_csv.unlink(missing_ok=True)
        tmp_xlsx.unlink(missing_ok=True)


def run_bbg_mirror_sync(
    *,
    ocw_root: Path | None = None,
    openclaw_workspace: Path | None = None,
    data_root: Path,
    scheduled_slot_utc: Any,
    timeout_s: float = 900.0,
    poll_interval_s: float = 15.0,
    dalton_pgids: set[int] | None = None,
    clock_fn: Any = time.monotonic,
    sleep_fn: Any = time.sleep,
    process_list_fn: Any = None,
    ps_list_fn: Any = None,
    redactor: HostSecretRedactor | None = None,
    stream_stdout: Any = None,
) -> tuple[int, str]:
    """Synchronously wait for OpenClaw BBG completion and atomically mirror/validate into `<data_root>/temp/`.

    On every poll iteration, prints a redacted progress line (`waiting for openclaw update: mtime=..., openclaw_running=...`)
    so the parent bridge's no-output timeout monitor is refreshed while waiting up to `timeout_s - 60`.
    """
    resolved_ocw_root = Path(ocw_root if ocw_root is not None else openclaw_workspace)
    list_fn = ps_list_fn or process_list_fn or _list_host_processes_ps
    active_redactor = redactor or HostSecretRedactor()
    slot_epoch = _parse_slot_utc_epoch(scheduled_slot_utc)
    own_pgids = set(dalton_pgids or set())
    try:
        own_pgids.add(os.getpgrp())
    except OSError:
        pass
    src_csv = resolved_ocw_root / "temp" / "bbg_data_latest.csv"
    deadline_wait_s = max(0.0, float(timeout_s) - 60.0)
    start_mono = float(clock_fn())
    progress_lines: list[str] = []

    while True:
        if src_csv.is_file():
            mtime_val = float(src_csv.stat().st_mtime)
            csv_ready = mtime_val >= slot_epoch
            mtime_str = f"{mtime_val:.3f}"
        else:
            csv_ready = False
            mtime_str = "missing"
        raw_rows = list_fn()
        norm_rows = _normalize_ps_rows(raw_rows)
        if norm_rows is None:
            busy = True
        else:
            busy = _has_non_dalton_bbg_refresh_process(
                norm_rows, dalton_pgids=own_pgids, data_root=data_root
            )
        if csv_ready and not busy:
            break
        progress_line = active_redactor.redact_text(
            f"waiting for openclaw update: mtime={mtime_str}, openclaw_running={busy}\n"
        )
        progress_lines.append(progress_line)
        if stream_stdout is not None:
            stream_stdout.write(progress_line)
            stream_stdout.flush()

        elapsed = float(clock_fn()) - start_mono
        if elapsed >= deadline_wait_s:
            err_out = {
                "ok": False,
                "error": "openclaw_not_updated",
                "reason": "openclaw_not_updated",
                "source": "openclaw_mirror",
            }
            final_line = active_redactor.redact_text(
                json.dumps(err_out, ensure_ascii=False) + "\n"
            )
            if stream_stdout is not None:
                return 1, final_line
            return 1, "".join(progress_lines) + final_line
        step = min(float(poll_interval_s), max(0.0, deadline_wait_s - elapsed))
        sleep_fn(step if step > 0 else float(poll_interval_s))

    rc, final_json = _stage_and_commit_bbg_mirror(
        ocw_root=resolved_ocw_root, data_root=data_root
    )
    redacted_final = active_redactor.redact_text(final_json)
    if stream_stdout is not None:
        return rc, redacted_final
    return rc, "".join(progress_lines) + redacted_final


def _run_host_task_gate_cli(argv: list[str]) -> int:
    """Entry point for the `--dalton-host-task-gate` wrapper process (§2.3 item 3).

    Blocks on stdin waiting for release signal (`b"GO\\n"`). If stdin closes before release,
    exits immediately without executing the task.
    """
    try:
        idx = argv.index(HOST_TASK_GATE_FLAG)
        rem = argv[idx + 1 :]
    except ValueError:
        return 1
    if not rem:
        return 1

    spec: dict[str, Any]
    try:
        parsed = json.loads(rem[0])
        if isinstance(parsed, dict) and len(rem) == 1:
            spec = parsed
        else:
            spec = {"mode": "command", "command_argv": [str(x) for x in rem]}
    except Exception:
        spec = {"mode": "command", "command_argv": [str(x) for x in rem]}

    release_line = sys.stdin.buffer.readline()
    if release_line not in (b"GO\n", b"1\n", b"RELEASE\n"):
        return 1

    mode = str(spec.get("mode") or "command")
    if mode == "hold_until_eof":
        try:
            sys.stdin.buffer.read()
        except Exception:
            pass
        return 0

    if mode == "mirror":
        redactor = HostSecretRedactor()
        rc, out_str = run_bbg_mirror_sync(
            ocw_root=Path(spec["ocw_root"]),
            data_root=Path(spec["data_root"]),
            scheduled_slot_utc=spec.get("scheduled_slot_utc"),
            timeout_s=float(spec.get("timeout_s", 900.0)),
            poll_interval_s=float(spec.get("poll_interval_s", 15.0)),
            redactor=redactor,
            stream_stdout=sys.stdout,
        )
        if out_str:
            sys.stdout.write(out_str)
            sys.stdout.flush()
        return int(rc)

    cmd_argv = spec.get("command_argv")
    if not isinstance(cmd_argv, list) or not cmd_argv:
        return 1
    cwd = spec.get("cwd") or None
    # DALTON-HOOK(host-job-secrets): re-enforce manifest allowlist in gate->child Hop 2
    hop2_entry = _resolve_host_task_manifest_entry(str(spec.get("job_key") or ""))
    hop2_secrets: dict[str, str] = {}
    hop2_plain_env: dict[str, str] = {}
    if hop2_entry is not None:
        for name in getattr(hop2_entry, "secret_names", ()):
            clean_name = str(name).strip()
            if clean_name and clean_name in os.environ:
                hop2_secrets[clean_name] = os.environ[clean_name]
        for k, v in (getattr(hop2_entry, "env", None) or {}).items():
            clean_k = str(k).strip()
            if clean_k and v is not None:
                hop2_plain_env[clean_k] = str(v)
    child = subprocess.Popen(
        [str(x) for x in cmd_argv],
        cwd=cwd,
        stdin=subprocess.DEVNULL,
        start_new_session=False,
        env=bridge_subprocess_env.build_host_task_subprocess_env(
            dict(os.environ),
            allowed_secrets=hop2_secrets,
            plain_env=hop2_plain_env,
        ),
    )

    def _forward_term(signum: int, _frame: Any) -> None:
        try:
            child.send_signal(signum)
        except Exception:
            pass

    signal.signal(signal.SIGTERM, _forward_term)
    signal.signal(signal.SIGINT, _forward_term)
    return int(child.wait())


_PREPARE_DROP = object()
_PREPARE_REQUEST_KEYS = frozenset({"period", "automation_execution_id"})
_BOUND_READ_KEYS = frozenset({
    "period",
    "date",
    "offset",
    "max_chars",
    "automation_execution_id",
})
_PREPARE_PUBLIC_KEYS = (
    "schema",
    "ok",
    "usable",
    "preparation_status",
    "reason",
    "period",
    "started_hkt_date",
    "authoritative_date",
    "execution_id",
    "digest_outcome",
    "digest_invoked",
    "tmtb_invoked",
    "reused",
    "emails_count",
    "priority_senders",
    "funda",
    "image_backlog",
    "tmtb",
    "hashes",
    "batch_id",
    "automation_execution_id",
)
_MARKET_DIGEST_DOCUMENT_KEYS = (
    "text",
    "emails",
    "tmtb_docs",
    "pending_snippets",
    "body",
    "content",
)
_MARKET_DIGEST_HEX64 = re.compile(r"^[0-9a-f]{64}$")
_MARKET_DIGEST_BAD_REQUEST = frozenset({
    "invalid_request",
    "unknown_field",
    "invalid_period",
    "invalid_date",
    "invalid_offset",
    "invalid_max_chars",
    "invalid_automation_execution",
})
_MARKET_DIGEST_UNAVAILABLE = frozenset({
    "not_configured",
    "config_invalid",
    "read_failed",
    "prepare_failed",
})


def _market_digest_code(value: object) -> str:
    if not isinstance(value, str) or not 1 <= len(value) <= 64:
        return ""
    if all(ch.isascii() and (ch.isalnum() or ch == "_") for ch in value):
        return value
    return ""


def _market_digest_unavailable(code: str, error: str) -> tuple[int, dict[str, Any]]:
    return 503, {"ok": False, "code": code, "error": error}


def _market_digest_http_status(result: Mapping[str, Any]) -> int:
    if result.get("ok") is True:
        return 200
    code = result.get("code")
    if code in _MARKET_DIGEST_BAD_REQUEST:
        return 400
    if code in _MARKET_DIGEST_UNAVAILABLE:
        return 503
    return 409


def _log_market_digest_read(status: int, payload: Mapping[str, Any]) -> None:
    logger.info(
        "market-digest read status=%s code=%s",
        status,
        _market_digest_code(payload.get("code")) or "-",
    )


def _log_market_digest_prepare(status: int, payload: Mapping[str, Any]) -> None:
    code = _market_digest_code(payload.get("code")) or _market_digest_code(
        payload.get("preparation_status")
    )
    logger.info("market-digest prepare status=%s code=%s", status, code or "-")


def _market_digest_reject(status: int, code: str, error: str) -> tuple[int, dict[str, Any]]:
    return status, {"ok": False, "code": code, "error": error}


def _canonical_automation_execution_id(value: object) -> str | None:
    if not isinstance(value, str) or len(value) != 36:
        return None
    try:
        parsed = uuid.UUID(value)
    except (TypeError, ValueError, AttributeError):
        return None
    if str(parsed) != value:
        return None
    return value


def _market_digest_iso_date(value: object) -> str | None:
    if not isinstance(value, str):
        return None
    text = value.strip()
    if len(text) != 10:
        return None
    try:
        parsed = datetime.strptime(text, "%Y-%m-%d")
    except ValueError:
        return None
    if parsed.strftime("%Y-%m-%d") != text:
        return None
    return text


def _market_digest_pathlike(value: str) -> bool:
    folded = value.lower()
    if value.startswith(("/", "~", "\\")) or "\\" in value or "file:" in folded:
        return True
    return any(
        needle in folded
        for needle in ("/users/", "/home/", "/var/", "/tmp/", "/private/", "/opt/")
    )


def _clean_prepare_value(value: Any) -> Any:
    if value is None or isinstance(value, bool):
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        if len(value) > 200 or _market_digest_pathlike(value):
            return _PREPARE_DROP
        return value
    if isinstance(value, list):
        cleaned_items = []
        for item in value:
            cleaned = _clean_prepare_value(item)
            if cleaned is _PREPARE_DROP:
                return _PREPARE_DROP
            cleaned_items.append(cleaned)
        return cleaned_items
    if isinstance(value, dict):
        cleaned_map: dict[str, Any] = {}
        for key, item in value.items():
            if (
                not isinstance(key, str)
                or not key
                or len(key) > 80
                or _market_digest_pathlike(key)
            ):
                continue
            cleaned = _clean_prepare_value(item)
            if cleaned is _PREPARE_DROP:
                continue
            cleaned_map[key] = cleaned
        return cleaned_map
    return _PREPARE_DROP


def _sanitize_prepare_result(result: Mapping[str, Any]) -> dict[str, Any]:
    cleaned: dict[str, Any] = {}
    for key in _PREPARE_PUBLIC_KEYS:
        if key not in result:
            continue
        value = _clean_prepare_value(result[key])
        if value is _PREPARE_DROP:
            continue
        cleaned[key] = value
    return cleaned


def _market_digest_prepare_response(result: object) -> tuple[int, dict[str, Any]]:
    if not isinstance(result, dict):
        return _market_digest_unavailable(
            "prepare_failed",
            "The market-digest batch could not be prepared.",
        )
    payload = _sanitize_prepare_result(result)
    try:
        encoded = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    except (TypeError, ValueError):
        return _market_digest_unavailable(
            "prepare_failed",
            "The market-digest batch could not be prepared.",
        )
    if len(encoded) > 128 * 1024:
        return _market_digest_reject(
            409,
            "response_exceeds_bound",
            "The prepare result does not fit in the response bound.",
        )
    return 200, payload


