def _reject_nonfinite(_name: str) -> None:
    raise ValueError("nonfinite")


def _parse_embed_stdout(stdout: str, expected: int) -> list[list[Any]]:
    try:
        loaded = json.loads(stdout, parse_constant=_reject_nonfinite)
    except (json.JSONDecodeError, ValueError, UnicodeError):
        raise _EmbedError("embed_failed") from None
    if not isinstance(loaded, dict) or loaded.get("ok") is not True:
        raise _EmbedError("embed_failed")
    embeddings = loaded.get("embeddings")
    if not isinstance(embeddings, list) or len(embeddings) != expected:
        raise _EmbedError("embed_failed")
    rows: list[list[Any]] = []
    for item in embeddings:
        if isinstance(item, (str, bytes)) or not isinstance(item, list):
            raise _EmbedError("embed_failed")
        rows.append(item)
    return rows


def _embed_texts(
    texts: list[str],
    model: str,
    *,
    python_executable: Path,
    script_path: Path,
    env: Mapping[str, str],
    runner: Any = None,
    now: Any = None,
    deadline_seconds: float = _EMBED_DEADLINE_S,
    child_timeout_seconds: float = _EMBED_CHILD_TIMEOUT_S,
) -> list[list[Any]]:
    """Embed ``texts`` in ordered batches. Failures raise and return nothing."""

    if not isinstance(texts, list) or not texts:
        raise _EmbedError("embed_failed")
    if not isinstance(model, str) or _OUTPUT_MODEL_RE.fullmatch(model) is None or ".." in model:
        raise _EmbedError("embed_failed")
    for text in texts:
        if not isinstance(text, str) or len(text) > _EMBED_CHUNK_CHARS or "\x00" in text:
            raise _EmbedError("embed_failed")
    clock = time.monotonic if now is None else now
    started = clock()
    command = _load_run_json_command() if runner is None else runner
    rows: list[list[Any]] = []
    argv = [str(python_executable), str(script_path)]
    for offset in range(0, len(texts), _EMBED_BATCH_SIZE):
        batch = texts[offset : offset + _EMBED_BATCH_SIZE]
        remaining = deadline_seconds - (clock() - started)
        if remaining <= 0:
            raise _EmbedError("embed_failed")
        payload = json.dumps(
            {"texts": batch, "model": model},
            ensure_ascii=False,
            allow_nan=False,
        ).encode("utf-8")
        if len(payload) > 2 * 1024 * 1024:
            raise _EmbedError("embed_failed")
        child = command(
            argv,
            env=env,
            timeout_seconds=min(child_timeout_seconds, remaining),
            stdout_limit_bytes=_EMBED_STDOUT_BYTES,
            stderr_limit_bytes=_EMBED_STDERR_BYTES,
            input_bytes=payload,
        )
        if (
            child.returncode != 0
            or child.timed_out
            or child.still_running
            or child.stdout_truncated
        ):
            raise _EmbedError("embed_failed")
        rows.extend(_parse_embed_stdout(child.stdout, len(batch)))
    if len(rows) != len(texts):
        raise _EmbedError("embed_failed")
    return rows


def _market_digest_embed_base_env(cfg: Any) -> dict[str, str]:
    base = {
        "PATH": os.environ.get("PATH", "").strip() or "/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin",
        "HOME": os.environ.get("HOME", "").strip() or str(Path.home()),
        "LANG": os.environ.get("LANG", "").strip() or "en_US.UTF-8",
        "PYTHONDONTWRITEBYTECODE": "1",
        "PYTHONIOENCODING": "utf-8",
    }
    proxy = str(getattr(cfg, "subprocess_proxy", "") or "").strip()
    if proxy:
        base["HTTP_PROXY"] = proxy
        base["HTTPS_PROXY"] = proxy
    return base


def _market_digest_embed_env(cfg: Any, repo_root: Path) -> dict[str, str] | None:
    env_path = getattr(cfg, "env_path", None)
    if not isinstance(env_path, Path):
        return None
    key = _read_env_file_dict(env_path).get("GEMINI_API_KEY", "").strip()
    if not key:
        return None
    return bridge_subprocess_env.build_nonarchive_subprocess_env(
        _market_digest_embed_base_env(cfg),
        extra_env={"GEMINI_API_KEY": key},
        allow_keys=("GEMINI_API_KEY",),
        repo_root=repo_root,
    )


def _market_digest_embed_script() -> Path:
    return Path(__file__).resolve().with_name("market_digest_embed.py")


def _make_market_digest_embedder(cfg: Any, prepare_cfg: Any) -> Any:
    script = _market_digest_embed_script()
    if not script.is_file():
        return _output_bridge_error(503, "output_failed", _OUTPUT_FAILED)
    try:
        env = _market_digest_embed_env(cfg, Path(prepare_cfg.repo_root))
    except Exception as exc:
        logger.warning("market-digest embedding env failed: %s", type(exc).__name__)
        return _output_bridge_error(503, "output_failed", _OUTPUT_FAILED)
    if env is None:
        return _output_bridge_error(503, "embedding_not_configured", _OUTPUT_EMBED_MISSING)
    python_executable = Path(prepare_cfg.python_executable)

    def embedder(texts: list[str], model: str) -> list[list[Any]]:
        return _embed_texts(
            texts,
            model,
            python_executable=python_executable,
            script_path=script,
            env=env,
        )

    return embedder


def _extract_tool_call_http_status(reply: Any) -> tuple[int, str]:
    """Derive HTTP status code/reason from a tools/call JSON-RPC reply when explicitly denied."""
    if not isinstance(reply, dict):
        return 200, "OK"
    result_obj = reply.get("result")
    if not isinstance(result_obj, dict):
        return 200, "OK"
    payload = result_obj.get("structuredContent")
    if not isinstance(payload, dict):
        for blk in result_obj.get("content") or []:
            if isinstance(blk, dict) and isinstance(blk.get("text"), str):
                try:
                    cand = json.loads(blk["text"])
                    if isinstance(cand, dict):
                        payload = cand
                        break
                except ValueError:
                    continue
    if not isinstance(payload, dict):
        return 200, "OK"
    http_override = payload.get("http_status")
    err_code = str(payload.get("error_code") or "").strip()
    if http_override == 403 or err_code == "capability_disabled":
        return 403, "Forbidden"
    if http_override == 503:
        return 503, "Service Unavailable"
    return 200, "OK"


def _run_market_digest_output(cfg: Any, action: str, body: Mapping[str, Any]) -> dict[str, Any]:
    root = getattr(cfg, "market_digest_state_root", None)
    prepare_path = getattr(cfg, "market_digest_prepare_config", None)
    output_path = getattr(cfg, "market_digest_output_config", None)
    if root is None or prepare_path is None or output_path is None:
        return _output_bridge_error(503, "not_configured", _OUTPUT_NOT_CONFIGURED)
    try:
        prepare_cfg = _load_market_digest_prepare_config(Path(prepare_path))
        output_cfg = _load_market_digest_output_config(Path(output_path))
    except Exception as exc:
        logger.warning("market-digest output config failed: %s", type(exc).__name__)
        return _output_bridge_error(503, "config_invalid", _OUTPUT_CONFIG_INVALID)
    try:
        read_root = Path(root).expanduser().resolve()
        prepare_root = Path(prepare_cfg.state_root).resolve()
        output_root = Path(output_cfg.input_state_root).resolve()
    except Exception as exc:
        logger.warning("market-digest output root check failed: %s", type(exc).__name__)
        return _output_bridge_error(503, "config_invalid", _OUTPUT_CONFIG_INVALID)
    if not (read_root == prepare_root == output_root):
        return _output_bridge_error(503, "config_invalid", _OUTPUT_ROOT_MISMATCH)
    execution_id = str(body["automation_execution_id"])
    period = str(body["period"])
    try:
        if action == "get":
            return _call_get_output(output_cfg, execution_id, period)
        if action == "save":
            return _call_save_output(output_cfg, execution_id, period, str(body["markdown"]))
        embedder = _make_market_digest_embedder(cfg, prepare_cfg)
        if isinstance(embedder, dict):
            return embedder
        return _call_finalize_output(
            output_cfg,
            execution_id,
            period,
            str(body["body_sha256"]),
            embedder,
        )
    except Exception as exc:
        logger.warning("market-digest output failed: %s", type(exc).__name__)
        return _output_bridge_error(503, "output_failed", _OUTPUT_FAILED)


def _market_digest_output_response(action: str, result: object) -> tuple[int, dict[str, Any]]:
    if not isinstance(result, dict):
        return _market_digest_unavailable("output_failed", _OUTPUT_FAILED)
    if _OUTPUT_BRIDGE in result:
        code = _market_digest_code(result.get("code")) or "output_failed"
        error = result.get("error")
        if (
            not isinstance(error, str)
            or len(error) > 200
            or "\n" in error
            or _market_digest_pathlike(error)
        ):
            error = _OUTPUT_FAILED
        status = result.get(_OUTPUT_BRIDGE)
        if status not in {400, 409, 503}:
            status = 503
        return int(status), {"ok": False, "code": code, "error": error}
    cleaned: dict[str, Any] = {}
    for key in _OUTPUT_PUBLIC_KEYS:
        if key not in result:
            continue
        value = _clean_prepare_value(result[key])
        if value is _PREPARE_DROP:
            continue
        cleaned[key] = value
    if action in {"get", "save"} and "markdown" in result:
        markdown = result.get("markdown")
        if not isinstance(markdown, str) or "\x00" in markdown:
            return _market_digest_reject(409, "body_invalid", "The saved markdown is not usable.")
        try:
            size = len(markdown.encode("utf-8"))
        except UnicodeError:
            return _market_digest_reject(409, "body_invalid", "The saved markdown is not usable.")
        if size > _OUTPUT_BODY_BYTES:
            return _market_digest_reject(
                409,
                "response_exceeds_bound",
                "The output result does not fit in the response bound.",
            )
        cleaned["markdown"] = markdown
    try:
        encoded = json.dumps(cleaned, ensure_ascii=False).encode("utf-8")
    except (TypeError, ValueError):
        return _market_digest_unavailable("output_failed", _OUTPUT_FAILED)
    limit = _OUTPUT_FINALIZE_RESPONSE_BYTES if action == "finalize" else _OUTPUT_RESPONSE_BYTES
    if len(encoded) > limit:
        return _market_digest_reject(
            409,
            "response_exceeds_bound",
            "The output result does not fit in the response bound.",
        )
    return 200, cleaned


async def _send_http(
    writer: asyncio.StreamWriter,
    status_code: int,
    status_text: str,
    body_Obj: dict[str, Any] | None = None,
    extra_headers: dict[str, str] | None = None,
) -> None:
    body_bytes = (
        json.dumps(body_Obj, ensure_ascii=False).encode("utf-8")
        if body_Obj is not None
        else b""
    )
    headers = [
        f"HTTP/1.1 {status_code} {status_text}",
        "Content-Type: application/json; charset=utf-8",
        f"Content-Length: {len(body_bytes)}",
        "Connection: close",
    ]
    if extra_headers:
        for k, v in extra_headers.items():
            headers.append(f"{k}: {v}")
    header_bytes = ("\r\n".join(headers) + "\r\n\r\n").encode("utf-8")
    writer.write(header_bytes + body_bytes)
    await writer.drain()
    writer.close()
    try:
        await writer.wait_closed()
    except Exception:
        pass


async def _send_http_file(
    writer: asyncio.StreamWriter,
    status_code: int,
    status_text: str,
    file_path: Path,
    *,
    content_type: str = "application/json; charset=utf-8",
    chunk_size: int = 65536,
) -> None:
    """Stream `file_path` over `writer` in fixed chunks without loading the entire file into memory."""
    file_size = file_path.stat().st_size
    headers = [
        f"HTTP/1.1 {status_code} {status_text}",
        f"Content-Type: {content_type}",
        f"Content-Length: {file_size}",
        "Connection: close",
    ]
    header_bytes = ("\r\n".join(headers) + "\r\n\r\n").encode("utf-8")
    writer.write(header_bytes)
    await writer.drain()
    with file_path.open("rb") as fh:
        while True:
            chunk = fh.read(chunk_size)
            if not chunk:
                break
            writer.write(chunk)
            await writer.drain()
    writer.close()
    try:
        await writer.wait_closed()
    except Exception:
        pass


def _extract_supplied_token(headers: Mapping[str, str]) -> str:
    """Extract bridge authentication token from `Authorization: Bearer <token>` or `X-Dalton-Bridge-Token`."""
    lowered = {k.lower(): v for k, v in headers.items()}
    auth_header = lowered.get("authorization", "").strip()
    if auth_header.lower().startswith("bearer "):
        return auth_header[7:].strip()
    bridge_header = lowered.get("x-dalton-bridge-token", "").strip()
    if bridge_header:
        return bridge_header
    return ""


def _is_valid_mcp_token(bridge: ResearchDataBridge, supplied_token: str) -> bool:
    """Return True if ``supplied_token`` matches ``DALTON_BRIDGE_TOKEN`` or ``DALTON_BRIDGE_ADMIN_TOKEN``."""
    if not supplied_token:
        return False
    supplied_bytes = supplied_token.encode("utf-8")
    mcp_token = (getattr(bridge.cfg, "token", "") or "").strip()
    admin_token = (getattr(bridge.cfg, "admin_token", "") or "").strip()
    matched = False
    if mcp_token and hmac.compare_digest(supplied_bytes, mcp_token.encode("utf-8")):
        matched = True
    if admin_token and hmac.compare_digest(supplied_bytes, admin_token.encode("utf-8")):
        matched = True
    return matched


async def _require_admin_token(
    bridge: ResearchDataBridge,
    headers: Mapping[str, str],
    writer: asyncio.StreamWriter,
) -> bool:
    """Verify ``DALTON_BRIDGE_ADMIN_TOKEN`` for all non-MCP routes (fail closed when unset)."""
    supplied_token = _extract_supplied_token(headers)
    expected_admin = (getattr(bridge.cfg, "admin_token", "") or "").strip()
    if not expected_admin or not supplied_token:
        await _send_http(
            writer, 401, "Unauthorized", {"ok": False, "error": "Unauthorized"}
        )
        return False
    supplied_bytes = supplied_token.encode("utf-8")
    if hmac.compare_digest(supplied_bytes, expected_admin.encode("utf-8")):
        return True
    mcp_token = (getattr(bridge.cfg, "token", "") or "").strip()
    if mcp_token and hmac.compare_digest(supplied_bytes, mcp_token.encode("utf-8")):
        await _send_http(
            writer, 403, "Forbidden", {"ok": False, "error": "Forbidden"}
        )
        return False
    await _send_http(
        writer, 401, "Unauthorized", {"ok": False, "error": "Unauthorized"}
    )
    return False


async def _handle_client(
    bridge: ResearchDataBridge,
    reader: asyncio.StreamReader,
    writer: asyncio.StreamWriter,
) -> None:
    _current_corr_id.set(uuid.uuid4().hex[:12])
    try:
        req_line_bytes = await asyncio.wait_for(reader.readline(), timeout=15.0)
        if not req_line_bytes:
            writer.close()
            return
        req_line = req_line_bytes.decode("utf-8", errors="replace").strip()
        parts = req_line.split(" ")
        if len(parts) < 2:
            await _send_http(writer, 400, "Bad Request", {"error": "Bad Request"})
            return
        method, raw_path = parts[0].upper(), parts[1]
        path = raw_path.split("?", 1)[0]

        # Read headers
        headers: dict[str, str] = {}
        while True:
            hline = await asyncio.wait_for(reader.readline(), timeout=15.0)
            if not hline or hline in (b"\r\n", b"\n"):
                break
            decoded = hline.decode("utf-8", errors="replace").strip()
            if ":" in decoded:
                hk, hv = decoded.split(":", 1)
                headers[hk.strip().lower()] = hv.strip()

        content_length = int(headers.get("content-length") or "0")
        if path == "/embed":
            max_bytes = bridge.cfg.embed_max_bytes
        elif path in ("/wiki/ingest", "/sales-notes/ingest"):
            # D1: both ingest bodies carry a base64 file beside the metadata,
            # so they share the wiki-ingest-sized envelope, not the MCP default.
            max_bytes = MAX_WIKI_INGEST_REQUEST_BYTES
        elif path in ("/feishu/doc/create", "/feishu/doc/append"):
            # C2: these bodies carry inline image bytes beside the markdown.
            max_bytes = MAX_FEISHU_DOC_REQUEST_BYTES
        elif path == "/internal/market-digest/output/save":
            # 128KiB of UTF-8 markdown expands when JSON-encoded. This route
            # alone accepts 1MiB. get and finalize stay on MAX_REQUEST_BYTES.
            max_bytes = _MARKET_DIGEST_OUTPUT_SAVE_REQUEST_BYTES
        elif path == "/internal/ai-finance/signals":
            # Three research objects do not fit the 256KiB default. This route
            # alone accepts 1MiB. Prepare and read stay on MAX_REQUEST_BYTES.
            max_bytes = _AI_FINANCE_SIGNALS_REQUEST_BYTES
        elif path == "/internal/ai-finance/report":
            # The daily and its news keys do not fit the 256KiB default.
            max_bytes = _AI_FINANCE_REPORT_REQUEST_BYTES
        else:
            max_bytes = MAX_REQUEST_BYTES
        if content_length > max_bytes:
            await _send_http(
                writer,
                413,
                "Payload Too Large",
                {"error": f"Request body exceeds {max_bytes} bytes"},
            )
            return

        body_bytes = b""
        if content_length > 0:
            read_timeout = (
                60.0
                if path
                in ("/wiki/ingest", "/sales-notes/ingest", "/feishu/doc/create", "/feishu/doc/append")
                else 15.0
            )
            body_bytes = await asyncio.wait_for(
                reader.readexactly(content_length), timeout=read_timeout
            )

        # Route 1: GET /healthz
        if method == "GET" and path == "/healthz":
            if bridge.server_version == "unknown":
                try:
                    await bridge.ensure_initialized()
                except Exception as exc:
                    logger.warning(
                        "Healthz init probe failed: %s (exit_code=%s)",
                        type(exc).__name__,
                        getattr(exc, "exit_code", None),
                    )
            conc_snap = bridge._get_concurrency().status_snapshot()
            rh_limiter = getattr(bridge, "_research_host_concurrency", None)
            rh_snap = rh_limiter.status_snapshot() if rh_limiter is not None else {}
            health_payload = {
                "ok": not bool(getattr(bridge, "_research_draining", False)),
                "status": "draining" if bool(getattr(bridge, "_research_draining", False)) else "ok",
                "draining": bool(getattr(bridge, "_research_draining", False)),
                "server_version": bridge.server_version,
                "max_inflight": bridge.cfg.max_inflight,
                "max_inflight_per_caller": getattr(bridge.cfg, "max_inflight_per_caller", 2),
                "max_inflight_unsigned": getattr(bridge.cfg, "max_inflight_unsigned", 1),
                "automation_reserved": getattr(bridge.cfg, "automation_reserved", 2),
                "fanout_grace_s": getattr(bridge.cfg, "fanout_grace_s", 20.0),
                "inflight": conc_snap["global_inflight"] + int(rh_snap.get("global_inflight", 0)),
                "queued": conc_snap["total_queued"] + int(rh_snap.get("total_queued", 0)),
                "global_queued": conc_snap["global_queued"] + int(rh_snap.get("global_queued", 0)),
                "ingest_inflight": int(getattr(bridge, "_ingest_inflight", 0)),
                "orphan_upstream": bridge._count_orphan_upstream(),
                "callers": conc_snap["callers"],
                "embed_max_inflight": bridge.cfg.embed_max_inflight,
                "embed_max_bytes": bridge.cfg.embed_max_bytes,
                "caller_budget_s": bridge.cfg.caller_budget_s,
                "alphaengine_get_document_today": bridge._read_usage_today(),
                "alphaengine_search_circuit_breaker": bridge._get_ae_search_breaker().snapshot(),
                "xreach": await bridge.probe_xreach_version(),
                "tmeet": await bridge.probe_tmeet_version(),
                "asr": bridge.asr_drain_status(),
            }
            await _send_http(writer, 200, "OK", health_payload)
            return

        # Route 2: /mcp (header token) or legacy /mcp/<token> (path token, deprecated)
        if path in ("/mcp", "/mcp/") or path.startswith("/mcp/"):
            if path in ("/mcp", "/mcp/"):
                supplied_token = _extract_supplied_token(headers)
            else:
                supplied_token = path[len("/mcp/") :].strip("/") or _extract_supplied_token(headers)

            if not _is_valid_mcp_token(bridge, supplied_token):
                # Constant-time rejection; NEVER log supplied_token or path
                await _send_http(writer, 401, "Unauthorized", {"error": "Unauthorized"})
                return

            if method in ("GET", "DELETE"):
                await _send_http(
                    writer, 405, "Method Not Allowed", {"error": "Method Not Allowed"}
                )
                return

            if method != "POST":
                await _send_http(
                    writer, 405, "Method Not Allowed", {"error": "Method Not Allowed"}
                )
                return

            try:
                rpc_msg = json.loads(body_bytes.decode("utf-8"))
            except Exception:
                await _send_http(
                    writer,
                    400,
                    "Bad Request",
                    {
                        "jsonrpc": "2.0",
                        "id": None,
                        "error": {"code": -32700, "message": "Parse error"},
                    },
                )
                return

            if not isinstance(rpc_msg, dict):
                await _send_http(
                    writer,
                    400,
                    "Bad Request",
                    {
                        "jsonrpc": "2.0",
                        "id": None,
                        "error": {"code": -32600, "message": "Invalid Request"},
                    },
                )
                return

            req_id = rpc_msg.get("id")
            rpc_method = str(rpc_msg.get("method") or "")
            rpc_params = rpc_msg.get("params") if isinstance(rpc_msg.get("params"), dict) else {}

            # JSON-RPC notifications (no id, e.g., notifications/initialized) -> 202 Accepted
            if "id" not in rpc_msg or req_id is None:
                await _send_http(writer, 202, "Accepted", None)
                return

            if rpc_method == "initialize":
                init_res = await bridge.ensure_initialized()
                offered_proto = str(rpc_params.get("protocolVersion") or "2024-11-05")
                adopted_proto = (
                    offered_proto
                    if offered_proto in ("2024-11-05", "2025-03-26", "2025-11-25")
                    else str(init_res.get("protocolVersion") or "2024-11-05")
                )
                reply = {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "result": {
                        "protocolVersion": adopted_proto,
                        "capabilities": {"tools": {}},
                        "serverInfo": {
                            "name": "researchdata",
                            "version": bridge.server_version,
                        },
                    },
                }
                await _send_http(writer, 200, "OK", reply)
                return

            if rpc_method == "ping":
                await _send_http(
                    writer, 200, "OK", {"jsonrpc": "2.0", "id": req_id, "result": {}}
                )
                return

            if rpc_method == "tools/list":
                tools = await bridge.get_filtered_tools()
                await _send_http(
                    writer,
                    200,
                    "OK",
                    {"jsonrpc": "2.0", "id": req_id, "result": {"tools": tools}},
                )
                return

            if rpc_method == "tools/call":
                if bool(getattr(bridge, "_research_draining", False)):
                    await _send_http(
                        writer,
                        503,
                        "Service Unavailable",
                        {
                            "ok": False,
                            "status": "draining",
                            "error_code": "service_draining",
                            "error": "Bridge is draining; retry shortly.",
                        },
                    )
                    return
                # Only trust caller identity from a verified HMAC-SHA256 signed
                # `X-Dalton-Caller-Token` (scoped per-request); unsigned headers
                # or failed/expired tokens never grant workspace/user buckets
                # or automation priority.
                has_per_request_scope = (
                    headers.get("x-dalton-caller-scope", "").strip().lower()
                    == "per-request"
                )
                supplied_caller_token = (
                    headers.get("x-dalton-caller-token", "").strip()
                    if has_per_request_scope
                    else ""
                )
                if supplied_caller_token:
                    verified_claims = bridge.verify_caller_token(supplied_caller_token)
                    caller_identity = (
                        {**verified_claims, "_caller_verified": True}
                        if verified_claims is not None
                        else {
                            "user": "",
                            "workspace": "",
                            "thread": "",
                            "run_origin": "",
                            "_caller_verified": False,
                        }
                    )
                else:
                    caller_identity = {
                        "user": "",
                        "workspace": "",
                        "thread": "",
                        "run_origin": "",
                        "_caller_verified": False,
                    }
                peer = writer.get_extra_info("peername")
                conn_id = (
                    str(peer[0])
                    if isinstance(peer, (tuple, list))
                    and peer
                    and isinstance(peer[0], str)
                    and peer[0].strip()
                    else f"sock-{id(writer)}"
                )
                reply = await bridge.handle_tools_call(
                    req_id,
                    rpc_params,
                    caller_identity=caller_identity,
                    conn_id=conn_id,
                    raw_caller_token=supplied_caller_token or None,
                )
                http_code, http_reason = _extract_tool_call_http_status(reply)
                await _send_http(writer, http_code, http_reason, reply)
                return

            # Unsupported method (e.g. server/discover probe -> -32601 so client falls back to legacy initialize)
            await _send_http(
                writer,
                200,
                "OK",
                {
                    "jsonrpc": "2.0",
                    "id": req_id,
                    "error": {"code": -32601, "message": f"Method not found: {rpc_method}"},
                },
            )
            return

        # Unified admin token gate for all non-MCP routes (/admin/drain, /embed, /jobs/*, and future routes)
        if not await _require_admin_token(bridge, headers, writer):
            return

        # Route 2b: GET/POST /admin/drain (admin token required; research & ingest graceful drain)
        if path == "/admin/drain":
            if method == "GET":
                await _send_http(writer, 200, "OK", bridge.research_drain_status())
                return
            if method == "POST":
                try:
                    drain_body = json.loads(body_bytes.decode("utf-8")) if body_bytes else {}
                    if not isinstance(drain_body, dict):
                        raise ValueError("Expected JSON object")
                except Exception:
                    await _send_http(writer, 400, "Bad Request", {"ok": False, "error": "Parse error"})
                    return
                status = bridge.set_research_draining(bool(drain_body.get("drain", True)))
                await _send_http(writer, 200, "OK", status)
                return
            await _send_http(writer, 405, "Method Not Allowed", {"error": "Method Not Allowed"})
            return

        # Route 3: POST /embed (admin token required; path tokens rejected)
        if path == "/embed":
            if method != "POST":
                await _send_http(
                    writer, 405, "Method Not Allowed", {"error": "Method Not Allowed"}
                )
                return
            try:
                embed_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(embed_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(writer, 400, "Bad Request", {"ok": False, "error": "Parse error"})
                return
            code, payload = await bridge.handle_embed(embed_body)
            status_label = "OK" if code == 200 else ("Bad Request" if code == 400 else "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        # Route 4: /jobs/ops (admin token required)
        if path == "/jobs/ops":
            if method != "GET":
                await _send_http(writer, 405, "Method Not Allowed", {"error": "Method Not Allowed"})
                return
            code, payload = await bridge.handle_get_ops_jobs()
            await _send_http(writer, code, "OK", payload)
            return

            await _send_http(writer, 404, "Not Found", {"error": "Not Found"})
            return

        # Route 5: POST /notify (behind the admin token gate above: only the
        # backend may push messages; a sandbox holds the MCP token only).
        # DALTON-HOOK(bridge-admin-token)
        if path == "/notify":
            if method != "POST":
                await _send_http(
                    writer, 405, "Method Not Allowed", {"error": "Method Not Allowed"}
                )
                return
            try:
                notify_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(notify_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(writer, 400, "Bad Request", {"ok": False, "error": "Parse error"})
                return
            code, payload = await bridge.handle_notify(notify_body)
            status_label = "OK" if code == 200 else "Bad Request"
            await _send_http(writer, code, status_label, payload)
            return

        # Route 6: POST /wiki/ingest (behind the admin token gate above; MCP token gets 403)
        # DALTON-HOOK(wiki-ingest)
        if path == "/wiki/ingest":
            if method != "POST":
                await _send_http(
                    writer, 405, "Method Not Allowed", {"ok": False, "error": "Method Not Allowed"}
                )
                return
            try:
                ingest_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(ingest_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(writer, 400, "Bad Request", {"ok": False, "error": "Parse error"})
                return
            code, payload = await bridge.handle_wiki_ingest(ingest_body)
            status_label = {
                200: "OK",
                400: "Bad Request",
                401: "Unauthorized",
                403: "Forbidden",
                409: "Conflict",
                410: "Gone",
                413: "Payload Too Large",
                422: "Unprocessable Entity",
                500: "Internal Server Error",
                502: "Bad Gateway",
                503: "Service Unavailable",
                504: "Gateway Timeout",
            }.get(code, "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        # Route 6b: POST /sales-notes/ingest (D1) — same admin gate, the
        # sell-side twin of the wiki ingest above.
        if path == "/sales-notes/ingest":
            if method != "POST":
                await _send_http(
                    writer, 405, "Method Not Allowed", {"ok": False, "error": "Method Not Allowed"}
                )
                return
            try:
                sn_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(sn_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(writer, 400, "Bad Request", {"ok": False, "error": "Parse error"})
                return
            code, payload = await bridge.handle_sales_notes_ingest(sn_body)
            status_label = {
                200: "OK",
                400: "Bad Request",
                401: "Unauthorized",
                403: "Forbidden",
                409: "Conflict",
                410: "Gone",
                413: "Payload Too Large",
                422: "Unprocessable Entity",
                500: "Internal Server Error",
                502: "Bad Gateway",
                503: "Service Unavailable",
                504: "Gateway Timeout",
            }.get(code, "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        # Route 7: POST /feishu/* (behind the admin token gate above; the
        # sandbox holds only the MCP token, so it can never reach Feishu).
        # DALTON-HOOK(feishu-docs)
        if path.startswith("/feishu/"):
            if method != "POST":
                await _send_http(
                    writer, 405, "Method Not Allowed", {"error": "Method Not Allowed"}
                )
                return
            try:
                feishu_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(feishu_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(writer, 400, "Bad Request", {"ok": False, "error": "Parse error"})
                return
            feishu_routes: dict[str, Any] = {
                "/feishu/doc/read": bridge.handle_feishu_doc_read,
                "/feishu/wiki/nodes": bridge.handle_feishu_wiki_nodes,
                "/feishu/wiki/node": bridge.handle_feishu_wiki_node,
                "/feishu/doc/create": bridge.handle_feishu_doc_create,
                "/feishu/doc/append": bridge.handle_feishu_doc_append,
                # C1: re-grant only, for shares that failed at doc creation.
                "/feishu/doc/grant": bridge.handle_feishu_doc_grant,
                # DALTON-HOOK(notify-routes): the chat-sending bot's name, so the
                # settings page can tell the user which bot to invite to a group,
                # and the bot's own chats, for the admin group-push card.
                "/feishu/bot-info": bridge.handle_feishu_bot_info,
                "/feishu/chats": bridge.handle_feishu_chats,
            }
            handler = feishu_routes.get(path)
            if handler is None:
                await _send_http(writer, 404, "Not Found", {"ok": False, "error": "Not Found"})
                return
            code, payload = await handler(feishu_body)
            status_label = {
                200: "OK",
                400: "Bad Request",
                403: "Forbidden",
                502: "Bad Gateway",
                503: "Service Unavailable",
            }.get(code, "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        # Route 8: /transcriptions* (A1b: behind the admin token gate above;
        # normal MCP token gets 403; accounting identity comes from the backend's
        # trusted `caller` payload, never from sandbox X-Dalton-* headers).
        if path == "/transcriptions" or path.startswith("/transcriptions/"):
            if path == "/transcriptions/drain":
                if method == "GET":
                    await _send_http(writer, 200, "OK", bridge.asr_drain_status())
                    return
                if method != "POST":
                    await _send_http(
                        writer, 405, "Method Not Allowed", {"ok": False, "error": "Method Not Allowed"}
                    )
                    return
                drain_flag = True
                if body_bytes.strip():
                    try:
                        parsed_drain = json.loads(body_bytes.decode("utf-8"))
                        if not isinstance(parsed_drain, dict):
                            raise ValueError("Expected JSON object")
                        if "drain" in parsed_drain:
                            drain_flag = bool(parsed_drain["drain"])
                    except Exception:
                        await _send_http(writer, 400, "Bad Request", {"ok": False, "error": "Parse error"})
                        return
                await _send_http(writer, 200, "OK", bridge.set_asr_draining(drain_flag))
                return

            if bridge.is_asr_disabled():
                await _send_http(
                    writer,
                    503,
                    "Service Unavailable",
                    {
                        "ok": False,
                        "error_code": "asr_disabled",
                        "error": "Bridge ASR is disabled (DALTON_BRIDGE_ASR_DISABLED=true)",
                    },
                )
                return

            if path == "/transcriptions":
                if method != "POST":
                    await _send_http(
                        writer, 405, "Method Not Allowed", {"ok": False, "error": "Method Not Allowed"}
                    )
                    return
                try:
                    asr_body = json.loads(body_bytes.decode("utf-8"))
                    if not isinstance(asr_body, dict):
                        raise ValueError("Expected JSON object")
                except Exception:
                    await _send_http(writer, 400, "Bad Request", {"ok": False, "error": "Parse error"})
                    return
                code, payload = await bridge.handle_transcription_submit(asr_body)
                status_label = {
                    200: "OK",
                    400: "Bad Request",
                    403: "Forbidden",
                    404: "Not Found",
                    409: "Conflict",
                    503: "Service Unavailable",
                }.get(code, "Bad Gateway")
                await _send_http(writer, code, status_label, payload)
                return

            subpath = path[len("/transcriptions/") :]
            parts = [p for p in subpath.split("/") if p]
            if len(parts) == 1:
                job_id = parts[0]
                if method != "GET":
                    await _send_http(
                        writer, 405, "Method Not Allowed", {"ok": False, "error": "Method Not Allowed"}
                    )
                    return
                code, payload = await bridge.handle_transcription_status(job_id)
                status_label = {
                    200: "OK",
                    400: "Bad Request",
                    404: "Not Found",
                    503: "Service Unavailable",
                }.get(code, "Bad Gateway")
                await _send_http(writer, code, status_label, payload)
                return

            if len(parts) == 2 and parts[1] == "result":
                job_id = parts[0]
                if method != "GET":
                    await _send_http(
                        writer, 405, "Method Not Allowed", {"ok": False, "error": "Method Not Allowed"}
                    )
                    return
                code, payload = await bridge.handle_transcription_result(job_id)
                status_label = {
                    200: "OK",
                    400: "Bad Request",
                    404: "Not Found",
                    409: "Conflict",
                    503: "Service Unavailable",
                }.get(code, "Bad Gateway")
                await _send_http(writer, code, status_label, payload)
                return

            if len(parts) == 3 and parts[1] == "result" and parts[2] == "raw":
                job_id = parts[0]
                if method != "GET":
                    await _send_http(
                        writer, 405, "Method Not Allowed", {"ok": False, "error": "Method Not Allowed"}
                    )
                    return
                code, raw_payload_or_path = await bridge.handle_transcription_raw_result(job_id)
                status_label = {
                    200: "OK",
                    400: "Bad Request",
                    404: "Not Found",
                    409: "Conflict",
                    503: "Service Unavailable",
                }.get(code, "Bad Gateway")
                if code == 200 and isinstance(raw_payload_or_path, Path):
                    await _send_http_file(writer, 200, "OK", raw_payload_or_path)
                else:
                    err_obj = (
                        raw_payload_or_path
                        if isinstance(raw_payload_or_path, dict)
                        else {"ok": False, "error": "Raw response unavailable"}
                    )
                    await _send_http(writer, code, status_label, err_obj)
                return

            if len(parts) == 2 and parts[1] in ("retry", "cancel"):
                job_id = parts[0]
                action = parts[1]
                if method != "POST":
                    await _send_http(
                        writer, 405, "Method Not Allowed", {"ok": False, "error": "Method Not Allowed"}
                    )
                    return
                action_body: dict[str, Any] = {}
                if body_bytes.strip():
                    try:
                        parsed_action = json.loads(body_bytes.decode("utf-8"))
                        if not isinstance(parsed_action, dict):
                            raise ValueError("Expected JSON object")
                        action_body = parsed_action
                    except Exception:
                        await _send_http(writer, 400, "Bad Request", {"ok": False, "error": "Parse error"})
                        return
                if action == "retry":
                    code, payload = await bridge.handle_transcription_retry(job_id, action_body)
                else:
                    code, payload = await bridge.handle_transcription_cancel(job_id, action_body)
                status_label = {
                    200: "OK",
                    400: "Bad Request",
                    404: "Not Found",
                    409: "Conflict",
                    503: "Service Unavailable",
                }.get(code, "Bad Gateway")
                await _send_http(writer, code, status_label, payload)
                return

            await _send_http(writer, 404, "Not Found", {"ok": False, "error": "Not Found"})
            return

        # POST /internal/market-digest/prepare. Admin token only; the gate above
        # rejects an MCP token before this route runs.
        if path == "/internal/market-digest/prepare":
            if method != "POST":
                await _send_http(
                    writer,
                    405,
                    "Method Not Allowed",
                    {"ok": False, "error": "Method Not Allowed"},
                )
                return
            try:
                prepare_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(prepare_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(
                    writer, 400, "Bad Request", {"ok": False, "error": "Parse error"}
                )
                return
            code, payload = await bridge.handle_market_digest_prepare(prepare_body)
            status_label = {
                200: "OK",
                400: "Bad Request",
                405: "Method Not Allowed",
                409: "Conflict",
                503: "Service Unavailable",
            }.get(code, "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        # POST /internal/market-digest/read. Admin token only; the gate above
        # rejects an MCP token before this route runs. Unknown JSON fields are
        # rejected by the helper. automation_execution_id is removed before that
        # helper when the tool sends it.
        if path == "/internal/market-digest/read":
            if method != "POST":
                await _send_http(
                    writer,
                    405,
                    "Method Not Allowed",
                    {"ok": False, "error": "Method Not Allowed"},
                )
                return
            try:
                digest_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(digest_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(
                    writer, 400, "Bad Request", {"ok": False, "error": "Parse error"}
                )
                return
            code, payload = await bridge.handle_market_digest_read(digest_body)
            status_label = {
                200: "OK",
                400: "Bad Request",
                405: "Method Not Allowed",
                409: "Conflict",
                503: "Service Unavailable",
            }.get(code, "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        # POST /internal/ai-finance/prepare. Admin token only; the gate above
        # rejects a missing token and an MCP token before this route runs.
        if path == "/internal/ai-finance/prepare":
            if method != "POST":
                await _send_http(
                    writer,
                    405,
                    "Method Not Allowed",
                    {"ok": False, "error": "Method Not Allowed"},
                )
                return
            try:
                ai_prepare_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(ai_prepare_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(
                    writer, 400, "Bad Request", {"ok": False, "error": "Parse error"}
                )
                return
            code, payload = await bridge.handle_ai_finance_prepare(ai_prepare_body)
            status_label = {
                200: "OK",
                400: "Bad Request",
                405: "Method Not Allowed",
                409: "Conflict",
                503: "Service Unavailable",
            }.get(code, "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        # POST /internal/ai-finance/read. Admin token only; the gate above
        # rejects a missing token and an MCP token before this route runs.
        if path == "/internal/ai-finance/read":
            if method != "POST":
                await _send_http(
                    writer,
                    405,
                    "Method Not Allowed",
                    {"ok": False, "error": "Method Not Allowed"},
                )
                return
            try:
                ai_read_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(ai_read_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(
                    writer, 400, "Bad Request", {"ok": False, "error": "Parse error"}
                )
                return
            code, payload = await bridge.handle_ai_finance_read(ai_read_body)
            status_label = {
                200: "OK",
                400: "Bad Request",
                405: "Method Not Allowed",
                409: "Conflict",
                503: "Service Unavailable",
            }.get(code, "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        # POST /internal/ai-finance/signals. Admin token only; the gate above
        # rejects a missing token and an MCP token before this route runs.
        if path == "/internal/ai-finance/signals":
            if method != "POST":
                await _send_http(
                    writer,
                    405,
                    "Method Not Allowed",
                    {"ok": False, "error": "Method Not Allowed"},
                )
                return
            try:
                ai_signals_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(ai_signals_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(
                    writer, 400, "Bad Request", {"ok": False, "error": "Parse error"}
                )
                return
            code, payload = await bridge.handle_ai_finance_signals(ai_signals_body)
            status_label = {
                200: "OK",
                400: "Bad Request",
                405: "Method Not Allowed",
                409: "Conflict",
                503: "Service Unavailable",
            }.get(code, "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        # POST /internal/ai-finance/report. Admin token only; the gate above
        # rejects a missing token and an MCP token before this route runs.
        if path == "/internal/ai-finance/report":
            if method != "POST":
                await _send_http(
                    writer,
                    405,
                    "Method Not Allowed",
                    {"ok": False, "error": "Method Not Allowed"},
                )
                return
            try:
                ai_report_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(ai_report_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(
                    writer, 400, "Bad Request", {"ok": False, "error": "Parse error"}
                )
                return
            code, payload = await bridge.handle_ai_finance_report(ai_report_body)
            status_label = {
                200: "OK",
                400: "Bad Request",
                405: "Method Not Allowed",
                409: "Conflict",
                503: "Service Unavailable",
            }.get(code, "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        # GET /internal/tracker-calendar/runtime-info. Admin token only; used by
        # migration probes to inspect the running bridge's actual gws account,
        # target calendar ID, active gcal backend, and research_home.
        if path == "/internal/tracker-calendar/runtime-info":
            if method != "GET":
                await _send_http(
                    writer,
                    405,
                    "Method Not Allowed",
                    {"ok": False, "error": "Method Not Allowed"},
                )
                return
            code, payload = await bridge.handle_tracker_calendar_runtime_info()
            status_label = {
                200: "OK",
                400: "Bad Request",
                405: "Method Not Allowed",
                503: "Service Unavailable",
            }.get(code, "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        # POST /internal/tracker-calendar/legacy-gws. Admin token only; the gate
        # above rejects a missing token and an MCP token before this route runs.
        if path == "/internal/tracker-calendar/legacy-gws":
            if method != "POST":
                await _send_http(
                    writer,
                    405,
                    "Method Not Allowed",
                    {"ok": False, "error": "Method Not Allowed"},
                )
                return
            try:
                gcal_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(gcal_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(
                    writer, 400, "Bad Request", {"ok": False, "error": "Parse error"}
                )
                return
            code, payload = await bridge.handle_tracker_calendar_legacy_gws(gcal_body)
            status_label = {
                200: "OK",
                400: "Bad Request",
                405: "Method Not Allowed",
                503: "Service Unavailable",
            }.get(code, "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        # POST /internal/market-digest/output/{get,save,finalize}. Admin token
        # only; the gate above rejects an MCP token before this route runs.
        if path in _OUTPUT_ACTIONS:
            if method != "POST":
                await _send_http(
                    writer,
                    405,
                    "Method Not Allowed",
                    {"ok": False, "error": "Method Not Allowed"},
                )
                return
            try:
                output_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(output_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(
                    writer, 400, "Bad Request", {"ok": False, "error": "Parse error"}
                )
                return
            code, payload = await bridge.handle_market_digest_output(
                _OUTPUT_ACTIONS[path],
                output_body,
            )
            status_label = {
                200: "OK",
                400: "Bad Request",
                405: "Method Not Allowed",
                409: "Conflict",
                503: "Service Unavailable",
            }.get(code, "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        # Route 9: POST /internal/data-tasks/host-run and POST /internal/data-tasks/host-kill
        # DALTON-HOOK(data-jobs): host data task execution behind the admin token gate (§2.3 item 3)
        if path in ("/internal/data-tasks/host-run", "/internal/data-tasks/host-kill"):
            if method != "POST":
                await _send_http(
                    writer, 405, "Method Not Allowed", {"ok": False, "error": "Method Not Allowed"}
                )
                return
            try:
                task_body = json.loads(body_bytes.decode("utf-8"))
                if not isinstance(task_body, dict):
                    raise ValueError("Expected JSON object")
            except Exception:
                await _send_http(writer, 400, "Bad Request", {"ok": False, "error": "Parse error"})
                return
            if path == "/internal/data-tasks/host-run":
                code, payload = await bridge.handle_data_task_host_run(task_body)
            else:
                code, payload = await bridge.handle_data_task_host_kill(task_body)
            status_label = {
                200: "OK",
                400: "Bad Request",
                403: "Forbidden",
                409: "Conflict",
                500: "Internal Server Error",
            }.get(code, "Bad Gateway")
            await _send_http(writer, code, status_label, payload)
            return

        await _send_http(writer, 404, "Not Found", {"error": "Not Found"})
    except Exception as exc:
        # P0 fix1 7: the request that died carries its correlation id in the
        # ContextVar (set at tools/call entry), so this last-resort line still
        # groups with the request's own sec_call_* / tools/call lines.
        corr = _current_corr_id.get()
        logger.error(
            "Unhandled bridge error: %s corr=%s",
            type(exc).__name__,
            corr or "-",
        )
        try:
            await _send_http(
                writer,
                500,
                "Internal Server Error",
                {
                    "jsonrpc": "2.0",
                    "id": None,
                    "error": {"code": -32603, "message": "Internal bridge error"},
                },
            )
        except Exception:
            pass


async def main() -> None:
    cfg = BridgeConfig()
    if not cfg.token:
        logger.error(
            "DALTON_BRIDGE_TOKEN is not set (checked env and ~/.config/dalton/researchdata-bridge.env)"
        )
        sys.exit(1)
    if not cfg.admin_token:
        logger.warning(
            "DALTON_BRIDGE_ADMIN_TOKEN is not set (checked env and ~/.config/dalton/researchdata-bridge.env); "
            "all admin endpoints (/embed, /jobs/*) will reject requests (fail closed)"
        )

    bridge = ResearchDataBridge(cfg)
    try:
        await bridge.ensure_initialized()
    except Exception as exc:
        logger.warning(
            "Startup initialize probe warning: %s (exit_code=%s)",
            type(exc).__name__,
            getattr(exc, "exit_code", None),
        )
    bridge.initialize_asr_on_startup()
    # DALTON-HOOK(data-jobs): recover host runner state and stop leftover process groups before serving (§2.3 item 3)
    try:
        await bridge.recover_host_runner_state_on_startup()
    except Exception as exc:
        logger.warning("Startup host data-task runner recovery warning: %s", type(exc).__name__)
    try:
        await bridge._get_alphaengine_search_cache().initialize()
    except Exception as exc:
        logger.warning("Startup AlphaEngine search cache init warning: %s", type(exc).__name__)

    server = await asyncio.start_server(
        lambda r, w: _handle_client(bridge, r, w),
        host=cfg.host,
        port=cfg.port,
    )
    logger.warning(
        "路径令牌已弃用 (POST /mcp/<token> is deprecated; use POST /mcp with Authorization: Bearer <token> or X-Dalton-Bridge-Token)"
    )
    logger.info(
        "Listening on http://%s:%d (server_version=%s, max_inflight=%d, caller_budget_s=%d)",
        cfg.host,
        cfg.port,
        bridge.server_version,
        cfg.max_inflight,
        cfg.caller_budget_s,
    )
    loop = asyncio.get_running_loop()
    main_task = asyncio.current_task()
    installed_signals: list[signal.Signals] = []
    if main_task is not None:
        def _cancel_on_signal() -> None:
            if not main_task.done():
                main_task.cancel()

        for sig in (signal.SIGTERM, signal.SIGINT):
            try:
                loop.add_signal_handler(sig, _cancel_on_signal)
                installed_signals.append(sig)
            except (NotImplementedError, RuntimeError, ValueError):
                pass
    try:
        async with server:
            await server.serve_forever()
    except asyncio.CancelledError:
        pass
    finally:
        for sig in installed_signals:
            try:
                loop.remove_signal_handler(sig)
            except (NotImplementedError, RuntimeError, ValueError):
                pass
        await bridge.close()


def _read_pyvenv_major_minor(cfg_path: Path) -> str | None:
    if not cfg_path.is_file():
        return None
    try:
        for line in cfg_path.read_text(encoding="utf-8").splitlines():
            if "=" not in line:
                continue
            k, v = (part.strip() for part in line.split("=", 1))
            if k in ("version", "version_info") and v:
                parts = v.split(".")
                if len(parts) >= 2 and parts[0].isdigit() and parts[1].isdigit():
                    return f"{parts[0]}.{parts[1]}"
    except OSError:
        return None
    return None


def _resolve_consensus_expected_mm(home_root: Path) -> str | None:
    ver_file = home_root / "state" / "venvs" / "consensus-estimates.python_version"
    if ver_file.is_file():
        try:
            raw = ver_file.read_text(encoding="utf-8").strip()
            if re.fullmatch(r"\d+\.\d+", raw):
                return raw
        except OSError:
            pass
    for cfg_cand in (
        home_root / "venvs" / "consensus-estimates" / "pyvenv.cfg",
        home_root / "state" / "venvs" / "consensus-estimates" / "pyvenv.cfg",
    ):
        mm = _read_pyvenv_major_minor(cfg_cand)
        if mm:
            return mm
    return None


def _inspect_venv_python_version(
    venv_dir: Path,
    py_path: Path,
    expected_mm: str | None,
) -> tuple[bool, str | None, str | None]:
    """Read a venv's Python version offline without spawning a subprocess."""
    detected: str | None = None
    cfg_path = venv_dir / "pyvenv.cfg"
    if cfg_path.is_file():
        try:
            for line in cfg_path.read_text(encoding="utf-8").splitlines():
                if "=" not in line:
                    continue
                k, v = (part.strip() for part in line.split("=", 1))
                if k in ("version", "version_info") and v:
                    detected = v
                    break
        except OSError:
            pass
    if not detected and (venv_dir / "lib").is_dir():
        for cand in sorted((venv_dir / "lib").iterdir()):
            if cand.is_dir() and cand.name.startswith("python3."):
                detected = cand.name.removeprefix("python")
                break
    if not detected:
        resolved_name = py_path.resolve().name
        m = re.search(r"python(\d+\.\d+(?:\.\d+)?)", resolved_name)
        if m:
            detected = m.group(1)
    mm = ".".join(detected.split(".")[:2]) if detected else ""
    if expected_mm is None:
        if detected and not detected.startswith("3."):
            return False, detected, f"version_mismatch_{detected}"
        return True, detected, None
    if mm == expected_mm:
        return True, detected, None
    err = f"version_mismatch_{detected}" if detected else "version_unknown"
    return False, detected, err


def _probe_tcp_port(host: str, port: int, timeout_s: float = 0.5) -> bool:
    try:
        with socket.create_connection((host, port), timeout=timeout_s):
            return True
    except Exception:
        return False


def _probe_launchd_label_loaded(
    label: str,
    *,
    uid: int | None = None,
    launchctl_bin: str | None = None,
) -> bool | None:
    """Return True if `launchctl print gui/<uid>/<label>` exits 0, False if non-zero, None on error."""
    status = ResearchDataBridge._probe_launchd_label_status(
        label,
        uid=uid,
        launchctl_bin=launchctl_bin,
    )
    if status == "on":
        return True
    if status == "off":
        return False
    return None


def _check_host_services_status() -> dict[str, Any]:
    """Check host research services (8950/8943 TCP reachability and com.dalton.* launchd labels)."""
    ae_port = int(os.environ.get("ALPHAENGINE_MCP_PORT", "8950"))
    gp_port = int(os.environ.get("GUIDEPOINT_PROXY_PORT", "8943"))

    specs: tuple[tuple[str, int | None, str], ...] = (
        (
            "alphaengine_mcp",
            ae_port,
            "com.dalton.alphaengine-mcp",
        ),
        (
            "alphaengine_desktop_watchdog",
            None,
            "com.dalton.alphaengine-desktop-watchdog",
        ),
        (
            "guidepoint_mcp_proxy",
            gp_port,
            "com.dalton.guidepoint-mcp-proxy",
        ),
    )

    out: dict[str, Any] = {}
    for key, port, label in specs:
        loaded = _probe_launchd_label_loaded(label)
        if loaded:
            active_label = label
            label_kind = "new"
        else:
            active_label = "unknown"
            label_kind = "unknown"

        entry: dict[str, Any] = {
            "new_label": label,
            "active_label": active_label,
            "label_kind": label_kind,
        }
        if port is not None:
            entry["port"] = port
            entry["reachable"] = _probe_tcp_port("127.0.0.1", port)
        out[key] = entry
    return out


def check_runtime_status(cfg: BridgeConfig | None = None) -> dict[str, Any]:
    """Read-only offline check of research runtime code, config, venvs, and local stores."""
    cfg = cfg or BridgeConfig()
    code_root = cfg.research_code
    home_root = cfg.research_home

    required_code_rel = (
        "config/data_sources.json",
        "config/eve_tracking_mirror.example.json",
        "scripts/researchdata_mcp.py",
        "scripts/data_gateway.py",
        "scripts/research_library.py",
        "scripts/research_library.sh",
        "scripts/research_images.py",
        "scripts/research_images.sh",
        "scripts/research_image_ingest.py",
        "scripts/alphaengine-mcp/export-image-source.mjs",
        "scripts/alphaengine-mcp/server.mjs",
        "scripts/funda_ai.py",
        "scripts/funda_ai.sh",
        "scripts/sales_notes_store.py",
        "scripts/tmtb_alphaengine_sync.py",
        "scripts/tmtb_alphaengine_sync.sh",
        "scripts/consensus_estimates.py",
        "scripts/consensus_estimates.sh",
        "scripts/consensus_estimates_requirements.txt",
        "scripts/xueqiu_posts.py",
        "scripts/feishu_send_card.py",
        "scripts/eve_tracking_mirror.py",
        "skills/13f-tracker/scripts/name_to_ticker.json",
        "skills/findata-analyst/run.sh",
        "skills/findata-analyst/scripts/findata_cli.py",
        "skills/cn-hk-findata/run.sh",
        "skills/cn-hk-findata/scripts/financemcp_adapter.py",
        "skills/company-wiki/run.sh",
        "skills/company-wiki/scripts/company_wiki_cli.py",
        "skills/market-digest/run.sh",
        "skills/market-digest/config.example.json",
        "skills/market-digest/scripts/market_digest_cli.py",
        "skills/employee-reviews/run.sh",
        "skills/employee-reviews/scripts/run.sh",
        "skills/employee-reviews/scripts/employee_reviews_cli.py",
        "skills/company-filings-alert/SKILL.md",
        "skills/company-filings-alert/run.sh",
        "skills/company-filings-alert/scripts/company_filings_alert_cli.py",
        "skills/company-filings-alert/scripts/edgar_enrich.py",
        "skills/guidepoint-transcript-search/SKILL.md",
        "skills/guidepoint-transcript-search/run.sh",
        "skills/guidepoint-transcript-search/scripts/gp_search.py",
    )
    dalton_host_service_code_rel = (
        "scripts/alphaengine-mcp/desktop-watchdog.sh",
        "scripts/alphaengine-mcp/self-test.sh",
        "scripts/alphaengine-mcp/server.test.mjs",
        "scripts/guidepoint_mcp_proxy.py",
        "scripts/guidepoint_mcp_oauth.py",
        "scripts/guidepoint_mcp_proxy_run.sh",
    )
    missing_code = [
        rel
        for rel in (
            *required_code_rel,
            *dalton_host_service_code_rel,
        )
        if not (code_root / rel).is_file()
    ]
    code_ok = code_root.is_dir() and not missing_code

    config_checks: dict[str, Any] = {}
    config_targets: tuple[tuple[str, Path], ...] = (
        ("data_sources", code_root / "config" / "data_sources.json"),
        ("company_wiki_config", code_root / "skills" / "company-wiki" / "config.json"),
        ("eve_tracking_mirror_config", home_root / "config" / "eve_tracking_mirror.json"),
        ("market_digest_config", home_root / "config" / "config.json"),
    )
    for label, p in config_targets:
        if not p.is_file():
            config_checks[label] = {"ok": False, "path": str(p), "error": "missing"}
        else:
            try:
                parsed = json.loads(p.read_text(encoding="utf-8"))
                entry: dict[str, Any] = {"ok": isinstance(parsed, dict), "path": str(p)}
                if label == "data_sources" and isinstance(parsed, dict):
                    entry["routes"] = len(parsed.get("routes") or [])
                config_checks[label] = entry
            except Exception as exc:
                config_checks[label] = {"ok": False, "path": str(p), "error": type(exc).__name__}

    env_vars = _read_env_file_dict(cfg.env_path) if isinstance(cfg.env_path, Path) else {}
    config_checks["bridge_env_file"] = {
        "ok": cfg.env_path.is_file(),
        "path": str(cfg.env_path),
        "present_keys": {
            k: bool((env_vars.get(k) or os.environ.get(k) or "").strip())
            for k in (
                "DALTON_BRIDGE_TOKEN",
                "DALTON_BRIDGE_ADMIN_TOKEN",
                "GEMINI_API_KEY",
                "EDGAR_IDENTITY",
                "FEISHU_APP_ID",
                "FEISHU_APP_SECRET",
            )
        },
    }
    configs_ok = all(
        bool(config_checks[k].get("ok"))
        for k in (
            "data_sources",
            "eve_tracking_mirror_config",
            "company_wiki_config",
            "market_digest_config",
        )
    )

    consensus_expected_mm = _resolve_consensus_expected_mm(home_root)
    specs: tuple[tuple[str, str | None], ...] = (
        ("findata-analyst", "3.12"),
        ("cn-hk-findata", "3.12"),
        ("company-wiki", "3.14"),
        ("market-digest", "3.13"),
        ("employee-reviews", "3.14"),
        ("consensus-estimates", consensus_expected_mm),
    )
    venv_checks: dict[str, Any] = {}
    for skill_name, expected_mm in specs:
        venv_dir = home_root / "venvs" / skill_name
        py_path = venv_dir / "bin" / "python"
        if not (py_path.is_file() and os.access(py_path, os.X_OK)):
            venv_checks[skill_name] = {
                "ok": False,
                "python": str(py_path),
                "expected_version": expected_mm,
                "error": "missing_or_not_executable",
            }
            continue
        ver_ok, ver, ver_err = _inspect_venv_python_version(venv_dir, py_path, expected_mm)
        venv_checks[skill_name] = {
            "ok": ver_ok,
            "python": str(py_path),
            "expected_version": expected_mm,
            "actual_version": ver,
            **({"error": ver_err} if ver_err else {}),
        }

    embed_py: Path | None = cfg.embed_python
    if embed_py is None:
        for cand in (
            home_root / "venvs" / "company-wiki" / "bin" / "python",
            home_root / "venvs" / "market-digest" / "bin" / "python",
        ):
            if cand.is_file() and os.access(cand, os.X_OK):
                embed_py = cand
                break
    embed_ok = embed_py is not None and embed_py.is_file() and os.access(embed_py, os.X_OK)
    venv_checks["embed_python"] = {
        "ok": embed_ok,
        "python": str(embed_py) if embed_py else None,
        "override_set": cfg.embed_python is not None,
    }
    venvs_ok = all(bool(v.get("ok")) for v in venv_checks.values())

    store_specs = (
        ("wiki_vectors_db", "file", home_root / "wiki" / "vectors.db"),
        ("wiki_companies_dir", "dir", home_root / "wiki" / "companies"),
        ("wiki_sectors_dir", "dir", home_root / "wiki" / "sectors"),
        ("market_digest_vectors_db", "file", home_root / "skills" / "market-digest" / "vectors.db"),
        ("market_digest_output_dir", "dir", home_root / "skills" / "market-digest" / "output"),
        ("sales_notes_manifest", "file", home_root / "state" / "sales-notes" / "manifest.jsonl"),
        ("funda_ai_db", "file", home_root / "state" / "funda-ai" / "index.sqlite"),
        ("research_images_db", "file", home_root / "state" / "research-images" / "index.sqlite"),
        ("tmtb_state_dir", "dir", home_root / "state" / "tmtb-alphaengine"),
        ("market_memory_dir", "dir", home_root / "market-memory"),
    )
    store_checks: dict[str, Any] = {}
    for name, kind, path in store_specs:
        if kind == "file":
            exists = path.is_file()
            info: dict[str, Any] = {"ok": exists, "kind": kind, "path": str(path)}
            if exists:
                try:
                    info["size_bytes"] = path.stat().st_size
                except OSError:
                    pass
            store_checks[name] = info
        else:
            exists = path.is_dir()
            store_checks[name] = {"ok": exists, "kind": kind, "path": str(path)}
    stores_ok = all(bool(v.get("ok")) for v in store_checks.values())

    host_services = _check_host_services_status()
    overall_ok = code_ok and configs_ok and venvs_ok and stores_ok
    return {
        "ok": overall_ok,
        "mode": "dalton_research",
        "code_ok": code_ok,
        "configs_ok": configs_ok,
        "venvs_ok": venvs_ok,
        "stores_ok": stores_ok,
        "paths": {
            "research_code": str(code_root),
            "research_home": str(home_root),
        },
        "code": {
            "ok": code_ok,
            "missing_files": missing_code,
        },
        "configs": config_checks,
        "venvs": venv_checks,
        "stores": store_checks,
        "host_services": host_services,
    }


def _run_check_runtime_cli() -> int:
    report = check_runtime_status()
    print(json.dumps(report, ensure_ascii=False, indent=2))
    return 0 if report.get("ok") else 1


if __name__ == "__main__":
    if HOST_TASK_GATE_FLAG in sys.argv:
        sys.exit(_run_host_task_gate_cli(sys.argv))
    if "--check-runtime" in sys.argv:
        sys.exit(_run_check_runtime_cli())
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        pass
